# =========================================================
_LIBRARY_BRIDGE_KEY = "_TAWJIHI_LIBRARY_CHANGE_BRIDGE_V1"

def _library_bridge_state() -> dict[str, Any]:
    state = getattr(builtins, _LIBRARY_BRIDGE_KEY, None)
    if not isinstance(state, dict):
        state = {"subscribers": [], "last_event": None, "published": 0}
        setattr(builtins, _LIBRARY_BRIDGE_KEY, state)
    return state

async def publish_library_change_event(payload: dict[str, Any]) -> int:
    """إرسال حدث فوري للمكتبة بعد نجاح تحديث materials.json.

    فشل أي مستمع لا يفشل قبول الملف؛ مراقبة materials.json تعالج الأمر احتياطياً.
    """
    state = _library_bridge_state()
    event = dict(payload or {})
    event.setdefault("source", "upload_bot_v3_1_13")
    event.setdefault("published_at", datetime.now(timezone.utc).isoformat())
    state["last_event"] = event
    state["published"] = int(state.get("published", 0)) + 1

    delivered = 0
    alive = []
    for callback in list(state.get("subscribers", [])):
        try:
            result = callback(event)
            if asyncio.iscoroutine(result):
                await result
            delivered += 1
            alive.append(callback)
        except Exception:
            log.exception("فشل إشعار مكتبة؛ ستلتقط المراقبة الاحتياطية تغيير materials.json")
            alive.append(callback)
    state["subscribers"] = alive
    return delivered
