_finish_slots = threading.BoundedSemaphore(FINISH_CONCURRENCY)
_process_slots: asyncio.Semaphore | None = None
_metrics_lock = threading.Lock()
_metrics = {'queued': 0, 'processing': 0, 'completed': 0, 'failed': 0}

def _metric(name: str, delta: int = 1) -> None:
    with _metrics_lock:
        _metrics[name] = max(0, int(_metrics.get(name, 0)) + delta)

def _retry_sync(label: str, fn, attempts: int = DRIVE_RETRY_ATTEMPTS):
    last = None
    for attempt in range(1, attempts + 1):
        try:
            return fn()
        except Exception as exc:
            last = exc
            if attempt >= attempts:
                break
            delay = min(30.0, DRIVE_RETRY_BASE_SECONDS * (2 ** (attempt - 1)))
            delay += random.uniform(0, min(1.0, delay * 0.2))
            log.warning('%s فشل (محاولة %s/%s): %s — إعادة بعد %.1fs', label, attempt, attempts, exc, delay)
            time.sleep(delay)
    raise last

