def get_embedded_brand_logo_bytes() -> bytes:
    """إرجاع صورة الشعار المدمجة بصيغة PNG دون الحاجة لملف خارجي."""
    import base64 as _base64
    return _base64.b64decode(BRAND_LOGO_BASE64)

def write_embedded_brand_logo(destination: Path | str | None = None) -> Path:
    """إنشاء نسخة مؤقتة من الشعار عند حاجة مكتبة PDF إلى مسار ملف."""
    target = Path(destination) if destination else DATA / "al_fahras_brand_logo.png"
    target.parent.mkdir(parents=True, exist_ok=True)
    if not target.exists() or target.stat().st_size == 0:
        target.write_bytes(get_embedded_brand_logo_bytes())
    return target


