# جميع حسابات Google Drive وتوزيع الفروع تُقرأ من متغير Render واحد.
# اسم المتغير: UPLOAD_CONFIG_JSON
# توكن Discord يبقى منفصلًا في: DISCORD_TOKEN_UPLOAD
def _load_upload_config_from_env() -> tuple[dict[str, dict[str, Any]], dict[str, list[str]]]:
    raw = os.getenv("UPLOAD_CONFIG_JSON", "").strip()
    if not raw:
        raise RuntimeError(
            "متغير UPLOAD_CONFIG_JSON غير موجود. "
            "انسخ محتوى ملف UPLOAD_CONFIG_JSON.txt إلى Render كمتغير واحد."
        )
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"قيمة UPLOAD_CONFIG_JSON ليست JSON صحيحة: السطر {exc.lineno}، العمود {exc.colno}"
        ) from exc

    accounts = payload.get("drive_accounts")
    branch_map = payload.get("branch_drive")

    if not isinstance(accounts, dict) or not accounts:
        raise RuntimeError("UPLOAD_CONFIG_JSON يجب أن يحتوي drive_accounts ككائن غير فارغ.")
    if not isinstance(branch_map, dict):
        raise RuntimeError("UPLOAD_CONFIG_JSON يجب أن يحتوي branch_drive ككائن.")

    normalized_accounts: dict[str, dict[str, Any]] = {}
    for raw_name, raw_cfg in accounts.items():
        name = str(raw_name).strip()
        if not name or not isinstance(raw_cfg, dict):
            continue

        cfg = dict(raw_cfg)
        oauth = cfg.get("oauth")
        if not isinstance(oauth, dict):
            oauth = {}

        cfg["label"] = str(cfg.get("label", name)).strip() or name
        cfg["branch"] = str(cfg.get("branch", "")).strip()
        cfg["root_folder_id"] = str(cfg.get("root_folder_id", "")).strip()
        cfg["pending_folder_id"] = str(cfg.get("pending_folder_id", "")).strip()
        cfg["enabled"] = cfg.get("enabled", True) is not False
        cfg["oauth"] = {
            "client_id": str(oauth.get("client_id", "")).strip(),
            "client_secret": str(oauth.get("client_secret", "")).strip(),
            "refresh_token": str(oauth.get("refresh_token", "")).strip(),
            "token_uri": str(
                oauth.get("token_uri", "https://oauth2.googleapis.com/token")
            ).strip() or "https://oauth2.googleapis.com/token",
        }
        normalized_accounts[name] = cfg

    normalized_branch_map: dict[str, list[str]] = {}
    for branch, names in branch_map.items():
        if not isinstance(names, list):
            names = []
        normalized_branch_map[str(branch)] = [
            str(name).strip()
            for name in names
            if str(name).strip() in normalized_accounts
        ]

    if not normalized_accounts:
        raise RuntimeError("لم يتم العثور على أي حساب صالح داخل UPLOAD_CONFIG_JSON.")

    return normalized_accounts, normalized_branch_map


