def now_iso(): return datetime.now(timezone.utc).isoformat()
def is_owner(uid:int)->bool: return uid in OWNER_IDS
def clean(s:str)->str: return (s.strip().replace('/','-').replace('\\','-')[:150] or 'بدون اسم')
def fmt_size(n:int)->str:
    x=float(n)
    for u in ('B','KB','MB','GB','TB'):
        if x<1024 or u=='TB': return f'{x:.2f} {u}'
        x/=1024
    return str(n)


def allowed_file(filename: str) -> bool:
    return Path(filename).suffix.lower() in ALLOWED_EXTENSIONS

def member_can_review(member) -> bool:
    if is_owner(member.id):
        return True
    role_ids = {int(x) for x in REVIEWER_ROLE_IDS if int(x)}
    if role_ids and hasattr(member, "roles"):
        return any(role.id in role_ids for role in member.roles)
    permissions = getattr(member, "guild_permissions", None)
    return bool(permissions and permissions.administrator)

def pending_count_for_user(user_id: int) -> int:
    with db() as c:
        row = c.execute(
            "SELECT COUNT(*) AS n FROM submissions WHERE user_id=? AND status='pending'",
            (user_id,)
        ).fetchone()
    return int(row["n"] or 0)

def last_submission_time(user_id: int) -> Optional[datetime]:
    with db() as c:
        row = c.execute(
            "SELECT created_at FROM submissions WHERE user_id=? ORDER BY id DESC LIMIT 1",
            (user_id,)
        ).fetchone()
    return datetime.fromisoformat(row["created_at"]) if row else None

def upload_permission_error(user_id: int) -> Optional[str]:
    if is_owner(user_id):
        return None
    if pending_count_for_user(user_id) >= MAX_PENDING_PER_USER:
        return f"لديك {MAX_PENDING_PER_USER} طلبات معلقة. انتظر مراجعة بعضها أولًا."
    last = last_submission_time(user_id)
    if last:
        passed = (datetime.now(timezone.utc) - last).total_seconds()
        if passed < UPLOAD_COOLDOWN_SECONDS:
            return f"انتظر {int(UPLOAD_COOLDOWN_SECONDS - passed) + 1} ثانية قبل إرسال طلب جديد."
    return None

async def report_error(title: str, exc: Exception | str) -> None:
    log.error("%s: %s", title, exc)
    try:
        ch = await channel(int(GENERAL.get("errors", 0) or 0))
        if ch:
            e = discord.Embed(title="⚠️ خطأ في نظام الرفع", color=discord.Color.red(),
                              timestamp=datetime.now(timezone.utc))
            e.add_field(name="المكان", value=title[:1024], inline=False)
            e.add_field(name="التفاصيل", value=str(exc)[:1024], inline=False)
            await ch.send(embed=e)
    except Exception:
        log.exception("تعذر إرسال الخطأ إلى قناة الأخطاء")

def sha256(path:Path)->str:
    h=hashlib.sha256()
    with path.open('rb') as f:
        for b in iter(lambda:f.read(4*1024*1024), b''): h.update(b)
    return h.hexdigest()

def insert(data:dict[str,Any])->int:
    ks=list(data)
    with _db_lock, db() as c:
        q=f"INSERT INTO submissions({','.join(ks)}) VALUES({','.join('?' for _ in ks)})"
        cur=c.execute(q,[data[k] for k in ks]); c.commit(); return int(cur.lastrowid)

def get_sub(i:int):
    with db() as c: return c.execute('SELECT * FROM submissions WHERE id=?',(i,)).fetchone()

def update_sub(i:int, **v):
    if not v:return
    with _db_lock, db() as c:
        c.execute('UPDATE submissions SET '+','.join(f'{k}=?' for k in v)+' WHERE id=?',[*v.values(),i]); c.commit()

def duplicate(account,path,digest):
    with db() as c:
        return c.execute('SELECT * FROM accepted_files WHERE drive_account=? AND full_path=? AND sha256=? ORDER BY id DESC LIMIT 1',(account,path,digest)).fetchone()

def set_setting(k,v):
    with _db_lock, db() as c:
        c.execute('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(k,v)); c.commit()

def get_setting(k):
    with db() as c:
        r=c.execute('SELECT value FROM settings WHERE key=?',(k,)).fetchone(); return r['value'] if r else None



# =========================================================
# نظام مجموعات المواد المشتركة — تخزين فعلي مرة واحدة
# =========================================================
def _stable_subject_id(branch: str, subject: str) -> str:
    raw = f"{branch}|{subject}".encode("utf-8")
    return "SUBJ_" + hashlib.sha1(raw).hexdigest()[:16].upper()


def ensure_subject_entity_sync(branch: str, subject: str, conn=None) -> str:
    subject_id = _stable_subject_id(branch, subject)
    own = conn is None
    c = conn or db()
    try:
        now = now_iso()
        c.execute(
            "INSERT INTO subject_entities(subject_id,branch,subject,created_at,updated_at) VALUES(?,?,?,?,?) "
            "ON CONFLICT(branch,subject) DO UPDATE SET updated_at=excluded.updated_at",
            (subject_id, branch, subject, now, now),
        )
        if own:
            c.commit()
        row = c.execute("SELECT subject_id FROM subject_entities WHERE branch=? AND subject=?", (branch, subject)).fetchone()
        return str(row["subject_id"])
    finally:
        if own:
            c.close()


def seed_default_shared_groups_sync(conn=None) -> None:
    """يزرع فقط المجموعات التي أكدها المستخدم، ولا يفترض تطابق مناهج أخرى."""
    own = conn is None
    c = conn or db()
    try:
        now = now_iso()
        defaults = [
            ("ARABIC_GENERAL", "العربية المشتركة — غير الصناعي", "اللغة العربية", None, "_SHARED/ARABIC_GENERAL"),
            ("ARABIC_INDUSTRIAL", "العربية — الصناعي", "اللغة العربية", None, "_SHARED/ARABIC_INDUSTRIAL"),
            ("TECH_SCI_INDUSTRIAL", "التكنولوجيا — العلمي والصناعي", "التكنولوجيا", None, "_SHARED/TECH_SCI_INDUSTRIAL"),
        ]
        for row in defaults:
            c.execute(
                "INSERT OR IGNORE INTO shared_groups(group_id,name,subject_name,drive_account,storage_root,is_active,created_by,created_at,updated_at) "
                "VALUES(?,?,?,?,?,1,0,?,?)", (*row, now, now)
            )
        arabic_general = ["علمي","أدبي","تجاري","زراعي","فندقي","اقتصاد منزلي","شرعي"]
        memberships = [("ARABIC_GENERAL", b, "اللغة العربية") for b in arabic_general]
        memberships += [("ARABIC_INDUSTRIAL", "صناعي", "اللغة العربية")]
        memberships += [("TECH_SCI_INDUSTRIAL", "علمي", "التكنولوجيا"), ("TECH_SCI_INDUSTRIAL", "صناعي", "التكنولوجيا")]
        for gid, branch, subject in memberships:
            if branch not in MATERIALS or subject not in MATERIALS.get(branch, []):
                continue
            sid = ensure_subject_entity_sync(branch, subject, c)
            c.execute(
                "INSERT OR IGNORE INTO shared_group_members(group_id,branch,subject,subject_id,added_by,created_at) VALUES(?,?,?,?,0,?)",
                (gid, branch, subject, sid, now),
            )
        if own:
            c.commit()
    finally:
        if own:
            c.close()


def shared_group_for(branch: str, subject: str):
    with db() as c:
        return c.execute(
            "SELECT g.*,m.subject_id FROM shared_group_members m JOIN shared_groups g ON g.group_id=m.group_id "
            "WHERE m.branch=? AND m.subject=? AND g.is_active=1",
            (branch, subject),
        ).fetchone()


def shared_group_members(group_id: str) -> list[sqlite3.Row]:
    with db() as c:
        return c.execute(
            "SELECT * FROM shared_group_members WHERE group_id=? ORDER BY branch", (group_id,)
        ).fetchall()


def resolve_storage_target(branch: str, subject: str, logical_path: str) -> dict[str, str | None]:
    logical_path = normalize_relative_folder_path(logical_path)
    parts = logical_path.split('/')
    if len(parts) < 2 or parts[0] != branch or parts[1] != subject:
        raise ValueError('المسار لا يطابق الفرع والمادة')
    sid = ensure_subject_entity_sync(branch, subject)
    group = shared_group_for(branch, subject)
    if not group:
        drive_account = account_for_storage(f'subject:{branch}:{subject}')
        return {
            'logical_path': logical_path,
            'storage_path': logical_path,
            'drive_account': drive_account,
            'shared_group_id': None,
            'subject_id': sid,
        }
    suffix = '/'.join(parts[2:])
    storage_path = normalize_relative_folder_path(f"{group['storage_root']}/{suffix}" if suffix else str(group['storage_root']))
    drive_account = account_for_storage(
        f"group:{group['group_id']}", preferred=str(group['drive_account'] or '').strip()
    )
    return {
        'logical_path': logical_path,
        'storage_path': storage_path,
        'drive_account': drive_account,
        'shared_group_id': str(group['group_id']),
        'subject_id': str(group['subject_id'] or sid),
    }


def logical_alias_paths(branch: str, subject: str, logical_path: str, group_id: str | None) -> list[tuple[str,str,str]]:
    if not group_id:
        return [(branch, subject, logical_path)]
    suffix = '/'.join(normalize_relative_folder_path(logical_path).split('/')[2:])
    result = []
    for member in shared_group_members(group_id):
        path = normalize_relative_folder_path(f"{member['branch']}/{member['subject']}/{suffix}" if suffix else f"{member['branch']}/{member['subject']}")
        result.append((str(member['branch']), str(member['subject']), path))
    return result or [(branch, subject, logical_path)]


def create_shared_group_sync(group_id: str, name: str, subject_name: str, actor_id: int,
                             drive_account: str = '', storage_root: str = '') -> None:
    gid = clean(group_id).replace(' ', '_').upper()
    if not gid or len(gid) < 3:
        raise ValueError('معرّف المجموعة قصير')
    root = normalize_relative_folder_path(storage_root or f'_SHARED/{gid}')
    if drive_account and drive_account not in DRIVE_ACCOUNTS:
        raise ValueError('حساب Drive غير موجود في الإعدادات')
    now = now_iso()
    with _db_lock, db() as c:
        c.execute(
            "INSERT INTO shared_groups(group_id,name,subject_name,drive_account,storage_root,is_active,created_by,created_at,updated_at) "
            "VALUES(?,?,?,?,?,1,?,?,?)",
            (gid, clean(name), clean(subject_name), drive_account or None, root, actor_id, now, now),
        )
        c.commit()
    audit('shared_group_create', actor_id, root, {'group_id':gid,'name':name,'subject':subject_name})


def add_shared_member_sync(group_id: str, branch: str, subject: str, actor_id: int) -> None:
    validate_branch_subject(branch, subject)
    with _db_lock, db() as c:
        group = c.execute("SELECT * FROM shared_groups WHERE group_id=? AND is_active=1", (group_id,)).fetchone()
        if not group:
            raise ValueError('المجموعة غير موجودة')
        if str(group['subject_name']) != subject:
            raise ValueError('اسم المادة لا يطابق مادة المجموعة')
        sid = ensure_subject_entity_sync(branch, subject, c)
        c.execute(
            "INSERT INTO shared_group_members(group_id,branch,subject,subject_id,added_by,created_at) VALUES(?,?,?,?,?,?) "
            "ON CONFLICT(branch,subject) DO UPDATE SET group_id=excluded.group_id,subject_id=excluded.subject_id,added_by=excluded.added_by,created_at=excluded.created_at",
            (group_id, branch, subject, sid, actor_id, now_iso()),
        )
        c.commit()
    audit('shared_group_add_member', actor_id, f'{branch}/{subject}', {'group_id':group_id})


def remove_shared_member_sync(branch: str, subject: str, actor_id: int) -> bool:
    with _db_lock, db() as c:
        row = c.execute("SELECT group_id FROM shared_group_members WHERE branch=? AND subject=?", (branch, subject)).fetchone()
        if not row:
            return False
        c.execute("DELETE FROM shared_group_members WHERE branch=? AND subject=?", (branch, subject))
        c.commit()
    audit('shared_group_remove_member', actor_id, f'{branch}/{subject}', {'group_id':row['group_id']})
    return True


def shared_group_preview_sync(group_id: str) -> dict[str, Any]:
    with db() as c:
        group = c.execute("SELECT * FROM shared_groups WHERE group_id=?", (group_id,)).fetchone()
        if not group:
            raise ValueError('المجموعة غير موجودة')
        members = c.execute("SELECT branch,subject FROM shared_group_members WHERE group_id=?", (group_id,)).fetchall()
        total = 0
        bytes_total = 0
        for m in members:
            row = c.execute(
                "SELECT COUNT(*) n,COALESCE(SUM(size_bytes),0) b FROM submissions WHERE branch=? AND subject=? AND status IN ('accepted','accepted_copy')",
                (m['branch'],m['subject']),
            ).fetchone()
            total += int(row['n'] or 0); bytes_total += int(row['b'] or 0)
        estimated_saved = max(0, bytes_total - (bytes_total // max(len(members),1))) if len(members)>1 else 0
        return {'group':dict(group),'members':[dict(x) for x in members],'files':total,'bytes':bytes_total,'estimated_saved':estimated_saved}

def path_options(branch,subject,category):
    if category=='مواد': return [f'{branch}/{subject}/مواد']
    if category=='امتحانات تجريبي': return [f'{branch}/{subject}/امتحانات تجريبي/{y}' for y in TRIAL_YEARS]
    if category=='وزاري':
        if branch=='علمي' and subject=='الرياضيات':
            return [f'{branch}/{subject}/وزاري/{s}/{y}' for s in ('جلسة أولى','جلسة ثانية') for y in WAZARI_YEARS]
        return [f'{branch}/{subject}/وزاري/{y}' for y in WAZARI_YEARS]
    return [f'{branch}/{subject}/{category}']


def standard_upload_paths(branch: str, subject: str) -> list[str]:
    paths: list[str] = []
    for category in CATEGORIES:
        paths.extend(path_options(branch, subject, category))
    return list(dict.fromkeys(paths))


def custom_upload_paths(branch: str, subject: str) -> list[str]:
    with db() as c:
        rows = c.execute(
            "SELECT full_path FROM custom_upload_folders WHERE branch=? AND subject=? AND is_active=1 ORDER BY full_path",
            (branch, subject)
        ).fetchall()
    return [str(row['full_path']) for row in rows]


def upload_paths_for_subject(branch: str, subject: str) -> list[str]:
    return list(dict.fromkeys(standard_upload_paths(branch, subject) + custom_upload_paths(branch, subject)))


def normalize_relative_folder_path(value: str) -> str:
    return '/'.join(clean(part) for part in str(value or '').strip().strip('/').split('/') if part.strip())


def validate_branch_subject(branch: str, subject: str) -> None:
    if branch not in BRANCHES:
        raise RuntimeError('الفرع غير صالح.')
    if subject not in MATERIALS.get(branch, []):
        raise RuntimeError(f'المادة غير موجودة ضمن فرع {branch}: {subject}')


def custom_folder_record(full_path: str):
    with db() as c:
        return c.execute(
            "SELECT * FROM custom_upload_folders WHERE full_path=? AND is_active=1",
            (full_path,)
        ).fetchone()


# ---------------- مكتبة الملفات والمزامنة ----------------
def display_filename(filename: str) -> str:
    name = Path(str(filename or '')).name.strip()
    return Path(name).stem.strip() or name or 'ملف'


SUBJECT_LIBRARY_ALIASES = {
    'التربية الإسلامية': 'دين',
    'اللغة العربية': 'عربي',
    'اللغة الإنجليزية': 'انجليزي',
    'الرياضيات': 'رياضيات',
    'الفيزياء': 'فيزياء',
    'الكيمياء': 'كيمياء',
    'الأحياء': 'أحياء',
    'التكنولوجيا': 'تكنو',
}


def library_json_path_parts(full_path: str) -> list[str]:
    """حوّل مسار بوت الرفع إلى نفس بنية materials.json الخاصة ببوت المكتبة."""
    parts = [part.strip() for part in str(full_path).split('/') if part.strip()]
    if len(parts) < 3:
        raise RuntimeError(f'مسار المكتبة غير صالح: {full_path}')

    branch, subject, category, *rest = parts
    subject = SUBJECT_LIBRARY_ALIASES.get(subject, subject)

    if category == 'وزاري':
        return [branch, subject, 'امتحانات', 'وزاري', *rest]
    if category == 'امتحانات تجريبي':
        return [branch, subject, 'امتحانات', 'تجريبي', *rest]
    if category == 'كتاب المادة':
        return [branch, subject, 'كتاب وتصنيف المادة', *rest]
    return [branch, subject, category, *rest]


def _load_materials_json_sync() -> dict[str, Any]:
    if not MATERIALS_FILE.exists():
        return {}
    try:
        with MATERIALS_FILE.open('r', encoding='utf-8') as f:
            data = json.load(f)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f'ملف materials.json غير صالح عند السطر {exc.lineno}: {exc.msg}') from exc
    if not isinstance(data, dict):
        raise RuntimeError('جذر materials.json يجب أن يكون كائن JSON.')
    return data


def _save_materials_json_atomic_sync(data: dict[str, Any]) -> None:
    """حفظ ذري مع نسخة احتياطية حتى لا يتلف الملف عند انقطاع التشغيل."""
    MATERIALS_FILE.parent.mkdir(parents=True, exist_ok=True)
    if MATERIALS_FILE.exists():
        stamp = datetime.now().strftime('%Y%m%d-%H%M%S-%f')
        backup = MATERIALS_BACKUP_DIR / f'materials-{stamp}.json'
        shutil.copy2(MATERIALS_FILE, backup)
        backups = sorted(MATERIALS_BACKUP_DIR.glob('materials-*.json'), key=lambda x: x.stat().st_mtime, reverse=True)
        for old_backup in backups[30:]:
            try:
                old_backup.unlink()
            except OSError:
                pass

    fd, tmp_name = tempfile.mkstemp(prefix='materials-', suffix='.tmp', dir=str(MATERIALS_FILE.parent))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='\n') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.write('\n')
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_name, MATERIALS_FILE)
    finally:
        if os.path.exists(tmp_name):
            os.unlink(tmp_name)


def _entry_url(value: Any) -> str:
    if isinstance(value, str): return value.strip()
    if isinstance(value, dict): return str(value.get("url") or value.get("رابط") or "").strip()
    return ""

def _unique_library_item_name(node: dict[str, Any], wanted: str, url: str) -> str:
    for existing_name, existing_value in node.items():
        if _entry_url(existing_value) == url: return existing_name
    if wanted not in node or _entry_url(node.get(wanted)) == url: return wanted
    number = 2
    while f"{wanted} ({number})" in node:
        if _entry_url(node.get(f"{wanted} ({number})")) == url: return f"{wanted} ({number})"
        number += 1
    return f"{wanted} ({number})"

def write_submission_to_materials_json_sync(full_path: str, display_name: str, url: str) -> dict[str, Any]:
    """أنشئ المسار الناقص وأضف اسم الملف والرابط داخل materials.json."""
    json_path = library_json_path_parts(full_path)
    with _materials_lock:
        data = _load_materials_json_sync()
        node: dict[str, Any] = data
        created_parts: list[str] = []

        for part in json_path:
            current = node.get(part)
            if current is None or current == {}:
                node[part] = {}
                created_parts.append(part)
            elif isinstance(current, str):
                old_value = current.strip()
                replacement: dict[str, Any] = {}
                if old_value and old_value != 'ضع_الرابط_هنا':
                    replacement['الرابط السابق'] = old_value
                node[part] = replacement
                created_parts.append(part)
            elif not isinstance(current, dict):
                node[part] = {}
                created_parts.append(part)
            node = node[part]

        final_name = _unique_library_item_name(node, display_name, url)
        already_present = _entry_url(node.get(final_name)) == url
        node[final_name] = {"title": final_name, "url": url, "description": "", "admin_only": False, "hidden": False}
        _save_materials_json_atomic_sync(data)

    return {
        'json_path': json_path,
        'created_parts': created_parts,
        'item_name': final_name,
        'already_present': already_present,
    }


def ensure_library_path_sync(full_path: str, branch: str, subject: str, category: str) -> bool:
    now = now_iso()
    with _db_lock, db() as c:
        existed = c.execute('SELECT 1 FROM library_paths WHERE full_path=?', (full_path,)).fetchone()
        c.execute('INSERT INTO library_paths(full_path,branch,subject,category,created_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(full_path) DO UPDATE SET branch=excluded.branch,subject=excluded.subject,category=excluded.category,updated_at=excluded.updated_at', (full_path,branch,subject,category,now,now))
        c.commit()
    return not bool(existed)


def queue_library_sync_sync(submission_id: int, reset: bool=False) -> None:
    now=now_iso()
    with _db_lock, db() as c:
        if reset:
            c.execute("INSERT INTO library_sync_jobs(submission_id,status,attempts,last_error,next_attempt_at,created_at,updated_at) VALUES(?,'pending',0,NULL,?,?,?) ON CONFLICT(submission_id) DO UPDATE SET status='pending',attempts=0,last_error=NULL,next_attempt_at=excluded.next_attempt_at,updated_at=excluded.updated_at", (submission_id,now,now,now))
        else:
            c.execute("INSERT OR IGNORE INTO library_sync_jobs(submission_id,status,attempts,last_error,next_attempt_at,created_at,updated_at) VALUES(?,'pending',0,NULL,?,?,?)", (submission_id,now,now,now))
        c.commit()


def sync_submission_to_library_sync(submission_id: int) -> dict[str,Any]:
    r=get_sub(submission_id)
    if not r: raise RuntimeError('الطلب غير موجود')
    if r['status'] not in ('accepted','accepted_copy'): raise RuntimeError('الطلب غير مقبول')
    url=str(r['source_url'] or r['drive_url'] or '').strip()
    if not url: raise RuntimeError('رابط الملف غير موجود')
    logical_path=str(r['logical_path'] or r['full_path'])
    aliases=logical_alias_paths(r['branch'],r['subject'],logical_path,r['shared_group_id'])
    now=now_iso(); shown=display_filename(r['filename'])
    json_results=[]; made=False
    for alias_branch, alias_subject, alias_path in aliases:
        made = ensure_library_path_sync(alias_path,alias_branch,alias_subject,r['category']) or made
        json_results.append(write_submission_to_materials_json_sync(alias_path, shown, url))
    json_result=json_results[0]
    with _db_lock, db() as c:
        c.execute("INSERT INTO library_items(submission_id,full_path,display_name,original_filename,url,drive_file_id,drive_account,source_kind,uploader_id,reviewer_id,created_at,updated_at,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1) ON CONFLICT(submission_id) DO UPDATE SET full_path=excluded.full_path,display_name=excluded.display_name,original_filename=excluded.original_filename,url=excluded.url,drive_file_id=excluded.drive_file_id,drive_account=excluded.drive_account,source_kind=excluded.source_kind,uploader_id=excluded.uploader_id,reviewer_id=excluded.reviewer_id,updated_at=excluded.updated_at,is_active=1", (submission_id,r['full_path'],shown,r['filename'],url,r['drive_file_id'],r['drive_account'],r['kind'],r['user_id'],r['reviewer_id'],now,now))
        if r['shared_group_id']:
            for alias_branch,alias_subject,alias_path in aliases:
                c.execute("INSERT OR REPLACE INTO shared_file_aliases(submission_id,group_id,branch,subject,logical_path,storage_path,url,created_at) VALUES(?,?,?,?,?,?,?,?)",(submission_id,r['shared_group_id'],alias_branch,alias_subject,alias_path,(r['storage_path'] or r['full_path']),url,now))
        c.execute("INSERT INTO library_audit_log(action,submission_id,actor_id,full_path,details,created_at) VALUES('sync',?,?,?,?,?)", (submission_id,r['reviewer_id'],logical_path,json.dumps({'url':url,'aliases':[x[2] for x in aliases]},ensure_ascii=False),now))
        c.execute("UPDATE library_sync_jobs SET status='done',last_error=NULL,updated_at=? WHERE submission_id=?",(now,submission_id)); c.commit()
    return {'created_path':made,'display_name':json_result['item_name'],'url':url,'json_path':json_result['json_path'],'created_parts':json_result['created_parts'],'already_present':json_result['already_present']}


def due_sync_jobs_sync(limit:int=25):
    with db() as c:
        return c.execute("SELECT * FROM library_sync_jobs WHERE status IN ('pending','retry') AND next_attempt_at<=? ORDER BY id LIMIT ?",(now_iso(),limit)).fetchall()


def mark_sync_failure_sync(job_id:int,error:str):
    with _db_lock, db() as c:
        row=c.execute('SELECT attempts FROM library_sync_jobs WHERE id=?',(job_id,)).fetchone(); attempts=int(row['attempts'] or 0)+1
        status='failed' if attempts>=LIBRARY_SYNC_MAX_ATTEMPTS else 'retry'
        delay=min(LIBRARY_SYNC_RETRY_SECONDS*(2**min(attempts-1,6)),3600)
        next_at=datetime.fromtimestamp(time.time()+delay,timezone.utc).isoformat()
        c.execute('UPDATE library_sync_jobs SET status=?,attempts=?,last_error=?,next_attempt_at=?,updated_at=? WHERE id=?',(status,attempts,error[:2000],next_at,now_iso(),job_id)); c.commit()
    return attempts,status


async def library_admin_log(title:str,description:str='',color=discord.Color.blurple()):
    ch=await channel(int(LIBRARY_ADMIN_CHANNEL_ID or 0))
    if ch:
        await ch.send(embed=discord.Embed(title=title,description=description[:4000] or None,color=color,timestamp=datetime.now(timezone.utc)))


async def sync_submission_to_library(submission_id:int,announce:bool=True):
    result=await asyncio.to_thread(sync_submission_to_library_sync,submission_id)
    # تحديث المكتبة فورياً بعد اكتمال الكتابة الذرية للبيانات.
    await publish_library_change_event({
        "action": "upsert",
        "submission_id": int(submission_id),
        "json_path": list(result.get("json_path", [])),
        "display_name": result.get("display_name"),
        "url": result.get("url"),
    })
    if announce:
        r=get_sub(submission_id); made='نعم' if result['created_path'] else 'لا'
        json_path = ' > '.join(result.get('json_path', []))
        created = '، '.join(result.get('created_parts', [])) or 'لا يوجد'
        await library_admin_log('✅ تمت مزامنة المكتبة',f"**مسار الرفع:** `{r['full_path']}`\n**مسار المكتبة:** `{json_path}`\n**الملف:** {result['display_name']}\n**تم إنشاء مسار جديد:** {made}\n**الأجزاء المنشأة:** {created}\n**الطلب:** `#{submission_id}`",discord.Color.green())
    return result


async def queue_and_try_library_sync(submission_id:int)->bool:
    await asyncio.to_thread(queue_library_sync_sync,submission_id,False)
    try:
        await sync_submission_to_library(submission_id,True); return True
    except Exception as exc:
        with db() as c: job=c.execute('SELECT id FROM library_sync_jobs WHERE submission_id=?',(submission_id,)).fetchone()
        if job: await asyncio.to_thread(mark_sync_failure_sync,int(job['id']),str(exc))
        await library_admin_log('⚠️ تأجلت مزامنة المكتبة',f"**الطلب:** `#{submission_id}`\nسيعيد البوت المحاولة تلقائيًا.\n**السبب:** {str(exc)[:1500]}",discord.Color.orange())
        return False


@tasks.loop(seconds=60)
async def library_sync_loop():
    for job in await asyncio.to_thread(due_sync_jobs_sync):
        try: await sync_submission_to_library(int(job['submission_id']),True)
        except Exception as exc:
            attempts,status=await asyncio.to_thread(mark_sync_failure_sync,int(job['id']),str(exc))
            if status=='failed':
                await library_admin_log('❌ فشلت مزامنة المكتبة نهائيًا',f"**الطلب:** `#{job['submission_id']}`\n**المحاولات:** `{attempts}`\n**السبب:** {str(exc)[:1500]}",discord.Color.red())

# ---------------- Google Drive ----------------
_services={}; _locks={}
_drive_quota_cache: dict[str, tuple[float, dict[str, Any]]] = {}


def drive_account_enabled(name: str) -> bool:
    override = get_setting(f"drive_account_enabled:{name}")
    if override is not None:
        return str(override) != "0"
    return DRIVE_ACCOUNTS.get(name, {}).get("enabled", True) is not False


def effective_root_folder_id(name: str) -> str:
    saved = get_setting(f"drive_root_folder_id:{name}")
    return str(saved or DRIVE_ACCOUNTS.get(name, {}).get("root_folder_id", "")).strip()


def effective_pending_folder_id(name: str) -> str:
    saved = get_setting(f"drive_pending_folder_id:{name}")
    return str(saved or DRIVE_ACCOUNTS.get(name, {}).get("pending_folder_id", "")).strip()


def pool_accounts(configured_only: bool = False) -> list[str]:
    """يعيد حسابات المخزن الموحّد المفعّلة بالترتيب الموجود في الإعدادات."""
    names: list[str] = []
    for name, cfg in DRIVE_ACCOUNTS.items():
        if not drive_account_enabled(name):
            continue
        if configured_only and not account_is_configured(name):
            continue
        names.append(str(name))
    return names


def branch_accounts(branch: str) -> list[str]:
    """للتوافق مع اللوحات القديمة؛ إن لم توجد قائمة للفرع يعرض المخزن الموحّد كله."""
    names = BRANCH_DRIVE.get(branch, [])
    if isinstance(names, str):
        names = [names]
    valid = [str(name).strip() for name in names if str(name).strip() in DRIVE_ACCOUNTS]
    return valid or pool_accounts()


def account_is_configured(name: str) -> bool:
    cfg = DRIVE_ACCOUNTS.get(name, {})
    if not drive_account_enabled(name):
        return False
    oauth = cfg.get("oauth", {})
    has_auth = bool(cfg.get("service_account_info")) or all(
        str(oauth.get(k, "")).strip() for k in ("client_id", "client_secret", "refresh_token")
    )
    return bool(effective_root_folder_id(name) and has_auth)


def drive_quota_sync(account_name: str, force: bool = False) -> dict[str, Any]:
    now = time.time()
    cached = _drive_quota_cache.get(account_name)
    if not force and cached and now - cached[0] < DRIVE_QUOTA_CACHE_SECONDS:
        return cached[1]

    result = service(account_name).about().get(
        fields="storageQuota(limit,usage,usageInDrive,usageInDriveTrash),user(displayName,emailAddress)"
    ).execute()
    quota = result.get("storageQuota", {})
    user = result.get("user", {})
    usage = int(quota.get("usage", 0) or 0)
    raw_limit = quota.get("limit")
    limit = int(raw_limit) if raw_limit not in (None, "") else None
    free = max(limit - usage, 0) if limit is not None else None
    percent = (usage / limit * 100.0) if limit else None
    data = {
        "usage": usage,
        "limit": limit,
        "free": free,
        "percent": percent,
        "email": str(user.get("emailAddress", "") or ""),
        "display_name": str(user.get("displayName", "") or ""),
    }
    _drive_quota_cache[account_name] = (now, data)
    return data


def _affinity_account(storage_key: str) -> str | None:
    with db() as c:
        row = c.execute(
            "SELECT drive_account FROM drive_storage_affinity WHERE storage_key=?", (storage_key,)
        ).fetchone()
    return str(row["drive_account"]) if row else None


def _save_affinity(storage_key: str, account_name: str) -> None:
    now = now_iso()
    with db() as c:
        c.execute(
            "INSERT INTO drive_storage_affinity(storage_key,drive_account,updated_at) VALUES(?,?,?) "
            "ON CONFLICT(storage_key) DO UPDATE SET drive_account=excluded.drive_account,updated_at=excluded.updated_at",
            (storage_key, account_name, now),
        )
        if storage_key.startswith("group:"):
            c.execute(
                "UPDATE shared_groups SET drive_account=?,updated_at=? WHERE group_id=?",
                (account_name, now, storage_key.split(':', 1)[1]),
            )
        c.commit()


def _account_has_room(name: str, required_bytes: int = 0) -> tuple[bool, dict[str, Any]]:
    health = drive_account_health_sync(name, auto_repair=True)
    if health.get("status") != "ok":
        raise RuntimeError(str(health.get("error") or "الحساب غير جاهز"))
    quota = drive_quota_sync(name)
    percent = quota.get("percent")
    free = quota.get("free")
    reserve = max(int(required_bytes or 0), DRIVE_MIN_FREE_BYTES)
    enough_percent = percent is None or float(percent) < DRIVE_FULL_PERCENT
    enough_bytes = free is None or int(free) >= reserve
    return bool(enough_percent and enough_bytes), quota


def account_for_storage(storage_key: str, required_bytes: int = 0, preferred: str = '') -> str:
    """يثبّت كل مادة/مجموعة على حساب، وينقل الرفع الجديد تلقائيًا عند امتلائه."""
    candidates = pool_accounts(configured_only=True)
    if not candidates:
        raise RuntimeError("لا يوجد أي حساب Google Drive مكتمل ومفعّل في DRIVE_ACCOUNTS.")

    sticky: list[str] = []
    if preferred and preferred in candidates:
        sticky.append(preferred)
    old = _affinity_account(storage_key)
    if old and old in candidates and old not in sticky:
        sticky.append(old)

    errors: list[str] = []
    for name in sticky:
        try:
            ok, quota = _account_has_room(name, required_bytes)
            if ok:
                _save_affinity(storage_key, name)
                return name
            errors.append(f"{name}: ممتلئ بنسبة {float(quota.get('percent') or 0):.1f}%")
        except Exception as exc:
            errors.append(f"{name}: {exc}")

    ranked: list[tuple[float, int, str]] = []
    for name in candidates:
        if name in sticky:
            continue
        try:
            ok, quota = _account_has_room(name, required_bytes)
            if not ok:
                errors.append(f"{name}: لا توجد مساحة كافية")
                continue
            percent = float(quota.get("percent")) if quota.get("percent") is not None else 0.0
            free = int(quota.get("free")) if quota.get("free") is not None else 2**63 - 1
            ranked.append((percent, -free, name))
        except Exception as exc:
            errors.append(f"{name}: {exc}")

    if not ranked:
        raise RuntimeError("لا يوجد حساب Drive متاح في المخزن الموحّد.\n" + "\n".join(errors[:15]))
    ranked.sort()
    chosen = ranked[0][2]
    _save_affinity(storage_key, chosen)
    return chosen


def account_for(branch: str) -> str:
    return account_for_storage(f"branch:{branch}")

def creds_for(cfg):
    if 'service_account_info' in cfg:
        return service_account.Credentials.from_service_account_info(cfg['service_account_info'],scopes=['https://www.googleapis.com/auth/drive'])
    o=cfg.get('oauth',{})
    cr=Credentials(token=o.get('token'),refresh_token=o.get('refresh_token'),token_uri=o.get('token_uri','https://oauth2.googleapis.com/token'),client_id=o.get('client_id'),client_secret=o.get('client_secret'),scopes=['https://www.googleapis.com/auth/drive'])
    if not cr.valid: cr.refresh(GoogleAuthRequest())
    return cr

def service(name):
    if name not in _services:
        _services[name]=build('drive','v3',credentials=creds_for(DRIVE_ACCOUNTS[name]),cache_discovery=False); _locks[name]=threading.RLock()
    return _services[name]

def qesc(s): return s.replace('\\','\\\\').replace("'","\\'")
def find_folder(s,parent,name):
    q=f"'{parent}' in parents and name='{qesc(name)}' and mimeType='application/vnd.google-apps.folder' and trashed=false"
    r=s.files().list(q=q,spaces='drive',fields='files(id)',pageSize=10,supportsAllDrives=True,includeItemsFromAllDrives=True).execute().get('files',[])
    return r[0]['id'] if r else None

def ensure_folder(s,parent,name):
    x=find_folder(s,parent,name)
    if x:return x
    return s.files().create(body={'name':name,'mimeType':'application/vnd.google-apps.folder','parents':[parent]},fields='id',supportsAllDrives=True).execute()['id']

def ensure_folder_with_status(s, parent, name):
    existing = find_folder(s, parent, name)
    if existing:
        return existing, False
    folder_id = s.files().create(
        body={'name': name, 'mimeType': 'application/vnd.google-apps.folder', 'parents': [parent]},
        fields='id', supportsAllDrives=True
    ).execute()['id']
    return folder_id, True


_drive_health_cache: dict[str, tuple[float, dict[str, Any]]] = {}


def _has_drive_credentials(name: str) -> bool:
    cfg = DRIVE_ACCOUNTS.get(name, {})
    oauth = cfg.get("oauth", {})
    return bool(cfg.get("service_account_info")) or all(
        str(oauth.get(k, "")).strip() for k in ("client_id", "client_secret", "refresh_token")
    )


def _persist_drive_state(name: str, *, root_id: str = "", pending_id: str = "", enabled: bool | None = None,
                         health_status: str = "", last_error: str = "", quota: dict[str, Any] | None = None) -> None:
    now = now_iso()
    if root_id:
        set_setting(f"drive_root_folder_id:{name}", root_id)
        DRIVE_ACCOUNTS[name]["root_folder_id"] = root_id
    if pending_id:
        set_setting(f"drive_pending_folder_id:{name}", pending_id)
        DRIVE_ACCOUNTS[name]["pending_folder_id"] = pending_id
    if enabled is not None:
        set_setting(f"drive_account_enabled:{name}", "1" if enabled else "0")
    quota = quota or {}
    with _db_lock, db() as c:
        c.execute(
            """INSERT INTO drive_account_state(
                 account_name,root_folder_id,pending_folder_id,enabled,health_status,last_error,email,
                 usage_bytes,limit_bytes,last_checked_at,updated_at
               ) VALUES(?,?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(account_name) DO UPDATE SET
                 root_folder_id=excluded.root_folder_id,pending_folder_id=excluded.pending_folder_id,
                 enabled=excluded.enabled,health_status=excluded.health_status,last_error=excluded.last_error,
                 email=excluded.email,usage_bytes=excluded.usage_bytes,limit_bytes=excluded.limit_bytes,
                 last_checked_at=excluded.last_checked_at,updated_at=excluded.updated_at""",
            (name, root_id or effective_root_folder_id(name), pending_id or effective_pending_folder_id(name),
             1 if drive_account_enabled(name) else 0, health_status, last_error,
             str(quota.get("email", "") or ""), int(quota.get("usage", 0) or 0),
             int(quota["limit"]) if quota.get("limit") is not None else None, now, now)
        )
        c.commit()


def load_drive_account_runtime_state() -> None:
    """يعيد IDs التي أنشأها البوت سابقًا من SQLite بعد كل تشغيل."""
    with db() as c:
        rows = c.execute("SELECT account_name,root_folder_id,pending_folder_id,enabled FROM drive_account_state").fetchall()
    for row in rows:
        name = str(row["account_name"])
        if name not in DRIVE_ACCOUNTS:
            continue
        if row["root_folder_id"]:
            DRIVE_ACCOUNTS[name]["root_folder_id"] = str(row["root_folder_id"])
            set_setting(f"drive_root_folder_id:{name}", str(row["root_folder_id"]))
        if row["pending_folder_id"]:
            DRIVE_ACCOUNTS[name]["pending_folder_id"] = str(row["pending_folder_id"])
            set_setting(f"drive_pending_folder_id:{name}", str(row["pending_folder_id"]))
        set_setting(f"drive_account_enabled:{name}", "1" if int(row["enabled"] or 0) else "0")


def initialize_drive_account_sync(name: str, force: bool = False) -> dict[str, Any]:
    """يفحص الحساب، ينشئ مجلد المكتبة والانتظار، ويحفظ IDs تلقائيًا."""
    if name not in DRIVE_ACCOUNTS:
        raise RuntimeError("اسم حساب Drive غير موجود في الإعدادات.")
    if not _has_drive_credentials(name):
        raise RuntimeError("بيانات OAuth/Service Account غير مكتملة.")
    srv = service(name)
    quota = drive_quota_sync(name, force=True)
    root_id = effective_root_folder_id(name)
    root_created = False
    if root_id:
        try:
            meta = srv.files().get(fileId=root_id, fields="id,name,mimeType,trashed", supportsAllDrives=True).execute()
            if meta.get("trashed") or meta.get("mimeType") != "application/vnd.google-apps.folder":
                root_id = ""
        except Exception:
            root_id = ""
    if not root_id:
        found = find_folder(srv, "root", DRIVE_LIBRARY_ROOT_NAME)
        if found:
            root_id = str(found)
        else:
            root_id = str(srv.files().create(
                body={"name": DRIVE_LIBRARY_ROOT_NAME, "mimeType": "application/vnd.google-apps.folder", "parents": ["root"]},
                fields="id", supportsAllDrives=True
            ).execute()["id"])
            root_created = True
    pending_id = effective_pending_folder_id(name)
    pending_created = False
    if pending_id:
        try:
            meta = srv.files().get(fileId=pending_id, fields="id,mimeType,trashed", supportsAllDrives=True).execute()
            if meta.get("trashed") or meta.get("mimeType") != "application/vnd.google-apps.folder":
                pending_id = ""
        except Exception:
            pending_id = ""
    if not pending_id:
        pending_id, pending_created = ensure_folder_with_status(srv, root_id, DRIVE_PENDING_FOLDER_NAME)
    # اختبار كتابة صغير وآمن ثم حذفه
    probe = srv.files().create(
        body={"name": ".drive_write_test", "mimeType": "application/vnd.google-apps.folder", "parents": [root_id]},
        fields="id", supportsAllDrives=True
    ).execute()
    srv.files().delete(fileId=str(probe["id"]), supportsAllDrives=True).execute()
    _persist_drive_state(name, root_id=root_id, pending_id=pending_id, health_status="ok", quota=quota)
    result = {
        "name": name, "label": DRIVE_ACCOUNTS[name].get("label", name), "email": quota.get("email", ""),
        "root_id": root_id, "pending_id": pending_id, "root_created": root_created,
        "pending_created": pending_created, "usage": quota.get("usage"), "limit": quota.get("limit"),
        "free": quota.get("free"), "percent": quota.get("percent"), "status": "ok"
    }
    _drive_health_cache[name] = (time.time(), result)
    return result


def drive_account_health_sync(name: str, force: bool = False, auto_repair: bool = True) -> dict[str, Any]:
    cached = _drive_health_cache.get(name)
    if not force and cached and time.time() - cached[0] < DRIVE_HEALTH_CACHE_SECONDS:
        return cached[1]
    if not drive_account_enabled(name):
        return {"name": name, "status": "disabled", "label": DRIVE_ACCOUNTS.get(name, {}).get("label", name)}
    try:
        if auto_repair:
            return initialize_drive_account_sync(name, force=force)
        quota = drive_quota_sync(name, force=force)
        root_id = effective_root_folder_id(name)
        if not root_id:
            raise RuntimeError("المجلد الرئيسي غير مهيأ")
        service(name).files().get(fileId=root_id, fields="id,trashed", supportsAllDrives=True).execute()
        result = {"name": name, "status": "ok", "root_id": root_id, **quota}
        _drive_health_cache[name] = (time.time(), result)
        return result
    except Exception as exc:
        _persist_drive_state(name, health_status="error", last_error=str(exc))
        result = {"name": name, "status": "error", "error": str(exc), "label": DRIVE_ACCOUNTS.get(name, {}).get("label", name)}
        _drive_health_cache[name] = (time.time(), result)
        return result


def initialize_all_drive_accounts_sync() -> list[dict[str, Any]]:
    results: list[dict[str, Any]] = []
    for name in DRIVE_ACCOUNTS:
        if not drive_account_enabled(name):
            results.append({"name": name, "status": "disabled"})
            continue
        if not _has_drive_credentials(name):
            results.append({"name": name, "status": "unconfigured", "error": "بيانات الدخول ناقصة"})
            continue
        try:
            results.append(initialize_drive_account_sync(name, force=True))
        except Exception as exc:
            _persist_drive_state(name, health_status="error", last_error=str(exc))
            results.append({"name": name, "status": "error", "error": str(exc)})
    return results

def ensure_path_detailed(name: str, path: str, start_parent_id: str | None = None):
    cfg = DRIVE_ACCOUNTS[name]
    cur = str(start_parent_id or effective_root_folder_id(name)).strip()
    if not cur:
        raise RuntimeError(f'root_folder_id ناقص للحساب {name}')
    srv = service(name)
    created = 0
    skipped = 0
    with _locks[name]:
        for part in path.split('/'):
            cur, was_created = ensure_folder_with_status(srv, cur, clean(part))
            if was_created:
                created += 1
            else:
                skipped += 1
    return cur, created, skipped

def ensure_path(name,path):
    return ensure_path_detailed(name, path)[0]

def pending_folder(name):
    cfg=DRIVE_ACCOUNTS[name]
    if effective_pending_folder_id(name): return effective_pending_folder_id(name)
    s=service(name)
    with _locks[name]:
        pid = ensure_folder(s, effective_root_folder_id(name), DRIVE_PENDING_FOLDER_NAME)
        _persist_drive_state(name, pending_id=pid, health_status='ok')
        return pid

def upload_staging(name,path,filename):
    def operation():
        with _drive_io_slots:
            s=service(name)
            media=MediaFileUpload(str(path),mimetype=mimetypes.guess_type(filename)[0] or 'application/octet-stream',resumable=True,chunksize=8*1024*1024)
            req=s.files().create(body={'name':clean(filename),'parents':[pending_folder(name)]},media_body=media,fields='id,webViewLink',supportsAllDrives=True)
            resp=None
            while resp is None:
                _,resp=req.next_chunk(num_retries=3)
            fid=str(resp['id'])
            return fid,str(resp.get('webViewLink') or f'https://drive.google.com/file/d/{fid}/view')
    return _retry_sync(f'رفع الملف إلى Drive ({name})', operation)

def move_final(name,fid,path):
    s=service(name); target=ensure_path(name,path)
    old=','.join(s.files().get(fileId=fid,fields='parents',supportsAllDrives=True).execute().get('parents',[]))
    r=s.files().update(fileId=fid,addParents=target,removeParents=old or None,fields='id,webViewLink',supportsAllDrives=True).execute()
    return str(r.get('webViewLink') or f'https://drive.google.com/file/d/{fid}/view')

def delete_drive(name,fid): service(name).files().delete(fileId=fid,supportsAllDrives=True).execute()


def create_custom_upload_folder_sync(
    branch: str, subject: str, parent_relative_path: str, folder_name: str, actor_id: int
) -> dict[str, Any]:
    validate_branch_subject(branch, subject)
    parent_relative_path = normalize_relative_folder_path(parent_relative_path)
    folder_name = clean(folder_name)
    if not folder_name:
        raise RuntimeError('اسم المجلد فارغ.')

    base_path = f'{branch}/{subject}'
    parent_path = f'{base_path}/{parent_relative_path}' if parent_relative_path else base_path
    full_path = f'{parent_path}/{folder_name}'

    account = account_for(branch)
    srv = service(account)
    parent_id = ensure_path(account, parent_path)

    with _locks[account]:
        folder_id = find_folder(srv, parent_id, folder_name)
        created_on_drive = False
        if not folder_id:
            result = srv.files().create(
                body={'name': folder_name, 'mimeType': 'application/vnd.google-apps.folder', 'parents': [parent_id]},
                fields='id', supportsAllDrives=True
            ).execute()
            folder_id = str(result['id'])
            created_on_drive = True

    now = now_iso()
    with _db_lock, db() as c:
        c.execute(
            """INSERT INTO custom_upload_folders(
                 branch,subject,full_path,parent_path,folder_name,drive_account,drive_folder_id,created_by,is_active,created_at,updated_at
               ) VALUES(?,?,?,?,?,?,?,?,1,?,?)
               ON CONFLICT(full_path) DO UPDATE SET
                 parent_path=excluded.parent_path,folder_name=excluded.folder_name,
                 drive_account=excluded.drive_account,drive_folder_id=excluded.drive_folder_id,
                 is_active=1,updated_at=excluded.updated_at""",
            (branch, subject, full_path, parent_path, folder_name, account, folder_id, actor_id, now, now)
        )
        c.commit()

    return {
        'created_on_drive': created_on_drive, 'full_path': full_path, 'folder_id': folder_id,
        'account': account, 'url': f'https://drive.google.com/drive/folders/{folder_id}'
    }


def rename_custom_upload_folder_sync(full_path: str, new_name: str, actor_id: int) -> dict[str, Any]:
    full_path = '/'.join(part.strip() for part in str(full_path or '').strip().strip('/').split('/') if part.strip())
    row = custom_folder_record(full_path)
    if not row:
        raise RuntimeError('هذا المجلد غير مسجل كمجلد مضاف من لوحة الإدارة.')

    new_name = clean(new_name)
    if not new_name:
        raise RuntimeError('الاسم الجديد فارغ.')

    parent_path = str(row['parent_path'])
    new_full_path = f'{parent_path}/{new_name}'
    if new_full_path == full_path:
        return {'old_path': full_path, 'new_path': new_full_path, 'account': row['drive_account'],
                'folder_id': row['drive_folder_id'], 'url': f"https://drive.google.com/drive/folders/{row['drive_folder_id']}"}

    with db() as c:
        duplicate_row = c.execute(
            "SELECT 1 FROM custom_upload_folders WHERE full_path=? AND is_active=1",
            (new_full_path,)
        ).fetchone()
    if duplicate_row:
        raise RuntimeError('يوجد مجلد مسجل بهذا الاسم داخل نفس المسار.')

    account = str(row['drive_account'] or account_for(str(row['branch'])))
    folder_id = str(row['drive_folder_id'] or '')
    if not folder_id:
        srv = service(account)
        parent_id = ensure_path(account, parent_path)
        folder_id = str(find_folder(srv, parent_id, str(row['folder_name'])) or '')
    if not folder_id:
        raise RuntimeError('تعذر العثور على المجلد في Google Drive.')

    srv = service(account)
    with _locks[account]:
        parent_id = ensure_path(account, parent_path)
        existing = find_folder(srv, parent_id, new_name)
        if existing and str(existing) != folder_id:
            raise RuntimeError('يوجد مجلد آخر بهذا الاسم في Google Drive.')
        srv.files().update(
            fileId=folder_id, body={'name': new_name}, fields='id', supportsAllDrives=True
        ).execute()

    now = now_iso()
    old_prefix = full_path + '/'
    new_prefix = new_full_path + '/'
    with _db_lock, db() as c:
        rows = c.execute(
            "SELECT id,full_path,parent_path FROM custom_upload_folders WHERE is_active=1 AND (full_path=? OR full_path LIKE ?)",
            (full_path, old_prefix + '%')
        ).fetchall()
        for item in rows:
            item_full = str(item['full_path'])
            item_parent = str(item['parent_path'])
            changed_full = new_full_path if item_full == full_path else new_prefix + item_full[len(old_prefix):]
            changed_parent = parent_path if item_full == full_path else (
                new_full_path if item_parent == full_path else
                new_prefix + item_parent[len(old_prefix):] if item_parent.startswith(old_prefix) else item_parent
            )
            changed_name = new_name if item_full == full_path else changed_full.rsplit('/', 1)[-1]
            c.execute(
                "UPDATE custom_upload_folders SET full_path=?,parent_path=?,folder_name=?,updated_at=? WHERE id=?",
                (changed_full, changed_parent, changed_name, now, int(item['id']))
            )
        c.execute(
            "INSERT INTO library_audit_log(action,actor_id,full_path,details,created_at) VALUES('rename_custom_folder',?,?,?,?)",
            (actor_id, new_full_path, json.dumps({'old_path': full_path}, ensure_ascii=False), now)
        )
        c.commit()

    return {
        'old_path': full_path, 'new_path': new_full_path, 'account': account,
        'folder_id': folder_id, 'url': f'https://drive.google.com/drive/folders/{folder_id}'
    }


def all_tree_paths(branch: str) -> list[str]:
    paths: list[str] = []
    for subject in MATERIALS[branch]:
        paths.extend(upload_paths_for_subject(branch, subject))
    # إزالة التكرارات مع الحفاظ على الترتيب
    return list(dict.fromkeys(paths))

def _job_cancel_key(job_id: int) -> str:
    return f"folder_job_cancel:{job_id}"

def create_folder_job_sync(branch: str, account: str, mode: str, actor_id: int, total_paths: int, force_root_id: str | None = None, force_root_name: str | None = None) -> int:
    now = now_iso()
    with _db_lock, db() as c:
        cur = c.execute(
            "INSERT INTO folder_build_jobs(branch,account,mode,status,total_paths,next_index,force_root_id,force_root_name,actor_id,created_at,updated_at) VALUES(?,?,?,'running',?,0,?,?,?,?,?)",
            (branch, account, mode, total_paths, force_root_id, force_root_name, actor_id, now, now)
        )
        c.commit()
        return int(cur.lastrowid)

def update_folder_job_sync(job_id: int, **fields):
    if not fields:
        return
    fields['updated_at'] = now_iso()
    keys = list(fields)
    sql = ','.join(f"{k}=?" for k in keys)
    with _db_lock, db() as c:
        c.execute(f"UPDATE folder_build_jobs SET {sql} WHERE id=?", [fields[k] for k in keys] + [job_id])
        c.commit()

def get_folder_job_sync(job_id: int):
    with db() as c:
        return c.execute("SELECT * FROM folder_build_jobs WHERE id=?", (job_id,)).fetchone()

def latest_resumable_job_sync(branch: str | None = None):
    with db() as c:
        if branch:
            return c.execute("SELECT * FROM folder_build_jobs WHERE branch=? AND status IN ('paused','failed') ORDER BY id DESC LIMIT 1", (branch,)).fetchone()
        return c.execute("SELECT * FROM folder_build_jobs WHERE status IN ('paused','failed') ORDER BY id DESC LIMIT 1").fetchone()

def folder_preview_sync(branch: str) -> dict[str, int]:
    paths = all_tree_paths(branch)
    missing_folders = 0
    existing_folders = 0
    failed = 0
    for account in branch_accounts(branch):
        if not account_is_configured(account):
            failed += len(paths)
            continue
        srv = service(account)
        root = str(DRIVE_ACCOUNTS[account]['root_folder_id'])
        with _locks[account]:
            for path in paths:
                cur = root
                try:
                    for part in path.split('/'):
                        found = find_folder(srv, cur, clean(part))
                        if found:
                            existing_folders += 1
                            cur = found
                        else:
                            # بعد أول مجلد مفقود، بقية أجزاء المسار ستكون مفقودة أيضًا
                            remaining = len(path.split('/')) - path.split('/').index(part)
                            missing_folders += remaining
                            break
                except Exception:
                    failed += 1
    return {'paths': len(paths), 'missing': missing_folders, 'existing': existing_folders, 'failed': failed}

async def create_branch_tree(branch: str, actor_id: int = 0, force_recreate: bool = False, resume_job_id: int | None = None) -> dict[str, int | str]:
    paths = all_tree_paths(branch)
    total_created = total_skipped = total_failed = 0
    last_job_id = 0
    for account in branch_accounts(branch):
        if not account_is_configured(account):
            total_failed += len(paths)
            continue
        start_index = 0
        force_root_id = None
        force_root_name = None
        mode = 'force' if force_recreate else 'normal'
        if resume_job_id:
            old = await asyncio.to_thread(get_folder_job_sync, resume_job_id)
            if not old or old['account'] != account or old['branch'] != branch:
                continue
            start_index = int(old['next_index'])
            force_root_id = old['force_root_id']
            force_root_name = old['force_root_name']
            mode = old['mode']
            job_id = int(old['id'])
            await asyncio.to_thread(update_folder_job_sync, job_id, status='running', last_error=None)
        else:
            if force_recreate:
                stamp = datetime.now().strftime('%Y-%m-%d_%H-%M-%S')
                force_root_name = f"إعادة إنشاء {branch} {stamp}"
                srv = service(account)
                root = str(DRIVE_ACCOUNTS[account]['root_folder_id'])
                with _locks[account]:
                    force_root_id = srv.files().create(
                        body={'name': force_root_name, 'mimeType': 'application/vnd.google-apps.folder', 'parents': [root]},
                        fields='id', supportsAllDrives=True
                    ).execute()['id']
                total_created += 1
            job_id = await asyncio.to_thread(create_folder_job_sync, branch, account, mode, actor_id, len(paths), force_root_id, force_root_name)
        last_job_id = job_id
        created = int((await asyncio.to_thread(get_folder_job_sync, job_id))['created_folders'] or 0)
        skipped = int((await asyncio.to_thread(get_folder_job_sync, job_id))['skipped_folders'] or 0)
        failed = int((await asyncio.to_thread(get_folder_job_sync, job_id))['failed_paths'] or 0)
        for idx in range(start_index, len(paths)):
            if get_setting(_job_cancel_key(job_id)) == '1':
                await asyncio.to_thread(update_folder_job_sync, job_id, status='paused', next_index=idx, created_folders=created, skipped_folders=skipped, failed_paths=failed)
                total_created += created; total_skipped += skipped; total_failed += failed
                return {'created': total_created, 'skipped': total_skipped, 'failed': total_failed, 'status': 'paused', 'job_id': job_id}
            path = paths[idx]
            try:
                _, c, s = await asyncio.to_thread(ensure_path_detailed, account, path, force_root_id)
                created += c
                skipped += s
            except Exception as exc:
                failed += 1
                await report_error(f"إنشاء المسار {path} في {account}", exc)
                await asyncio.to_thread(update_folder_job_sync, job_id, last_error=str(exc)[:1800])
            if idx % 10 == 0 or idx == len(paths)-1:
                await asyncio.to_thread(update_folder_job_sync, job_id, next_index=idx+1, created_folders=created, skipped_folders=skipped, failed_paths=failed)
                await asyncio.sleep(0)
        await asyncio.to_thread(update_folder_job_sync, job_id, status='completed', next_index=len(paths), created_folders=created, skipped_folders=skipped, failed_paths=failed)
        set_setting(_job_cancel_key(job_id), '0')
        total_created += created; total_skipped += skipped; total_failed += failed
    await library_admin_log('📁 اكتملت عملية إنشاء المجلدات', f"**الفرع:** {branch}\n**أنشأ:** `{total_created}`\n**موجود مسبقًا:** `{total_skipped}`\n**فشل:** `{total_failed}`\n**رقم العملية:** `{last_job_id}`", discord.Color.green() if not total_failed else discord.Color.orange())
    return {'created': total_created, 'skipped': total_skipped, 'failed': total_failed, 'status': 'completed', 'job_id': last_job_id}

