def review_cid(branch,kind):
    if kind=='drive_link':return int(GENERAL.get('drive_links',0) or 0)
    return int(REVIEW_CHANNELS.get(branch) or GENERAL.get('review',0) or 0)

def embed_for(r):
    e=discord.Embed(title='🔗 رابط Drive بانتظار المراجعة' if r['kind']=='drive_link' else '📥 ملف بانتظار المراجعة',color=discord.Color.orange(),timestamp=datetime.fromisoformat(r['created_at']))
    e.add_field(name='👤 الرافع',value=f"<@{r['user_id']}>\n`{r['username']}`",inline=False)
    e.add_field(name='🌿 الفرع',value=r['branch'],inline=True); e.add_field(name='📚 المادة',value=r['subject'],inline=True); e.add_field(name='📂 التصنيف',value=r['category'],inline=True)
    e.add_field(name='📁 المسار الكامل',value=f"`{r['full_path']}`",inline=False); e.add_field(name='📄 اسم الملف',value=r['filename'],inline=False); e.add_field(name='📦 الحجم',value=fmt_size(r['size_bytes']),inline=True)
    e.add_field(name='🔍 فحص التكرار',value=(f"⚠️ مطابق لطلب {r['duplicate_of']}" if r['duplicate_of'] else '✅ غير مكرر'),inline=True)
    e.add_field(name='🕒 وقت الرفع',value=f"<t:{int(datetime.fromisoformat(r['created_at']).timestamp())}:F>",inline=False)
    if r['source_url']:e.add_field(name='🔗 الرابط',value=r['source_url'],inline=False)
    elif r['drive_url']:e.add_field(name='🔗 معاينة مؤقتة',value=r['drive_url'],inline=False)
    e.set_footer(text=f"رقم الطلب: {r['id']}"); return e

async def send_log(key,e):
    ch=await channel(int(GENERAL.get(key,0) or 0))
    if ch:await ch.send(embed=e)

async def post_review(i):
    r=get_sub(i); ch=await channel(review_cid(r['branch'],r['kind']))
    if not ch:raise RuntimeError('قناة المراجعة غير مضبوطة')
    m=await ch.send(embed=embed_for(r),view=ReviewView(i)); update_sub(i,review_channel_id=ch.id,review_message_id=m.id)

async def close_review(r,title,color):
    ch=await channel(int(r['review_channel_id'] or 0))
    if not ch or not r['review_message_id']:return
    try:
        m=await ch.fetch_message(int(r['review_message_id'])); e=embed_for(r); e.title=title; e.color=color; await m.edit(embed=e,view=None)
    except Exception:pass


