def folder_browser_text(state: State, relative_parts: list[str]) -> str:
    shown = ' > '.join([state.branch, state.subject, *relative_parts])
    return f'مكتبة رفع الملفات\nالمسار: {shown}\n\nاختر المجلد:'


class FolderBrowserView(UserFlowView):
    def __init__(self, state: State, relative_parts: list[str] | None = None, page: int = 0):
        super().__init__(state)
        self.relative_parts = list(relative_parts or [])
        children, selectable = folder_children(state, self.relative_parts)
        children = ordered_folder_children(state, self.relative_parts, children)
        columns = get_button_columns("folders")
        # نترك السطر الخامس لأزرار رجوع/السابق/التالي.
        page_size = columns * 4
        max_page = max((len(children) - 1) // page_size, 0)
        page = max(0, min(page, max_page))
        start = page * page_size
        shown = children[start:start + page_size]
        for index, child in enumerate(shown):
            self.add_item(FolderChildButton(state, self.relative_parts, child, index // columns))

        control_row = 4
        if page > 0:
            self.add_item(FolderPageButton(state, self.relative_parts, page - 1, 'السابق', control_row))
        if start + page_size < len(children):
            self.add_item(FolderPageButton(state, self.relative_parts, page + 1, 'التالي', control_row))
        self.add_item(FolderBackButton(state, self.relative_parts, control_row))


def flow_summary(state: State) -> str:
    shown = ' > '.join(part for part in state.full_path.split('/') if part)
    return (
        'مكتبة رفع الملفات\n'
        f'المسار: {shown}\n\n'
        f'المسار النهائي:\n`{state.full_path}`'
    )


