async def process_file(path,filename,user_id,username,branch,subject,category,full_path,kind):
    global _process_slots
    if _process_slots is None:
        _process_slots = asyncio.Semaphore(PROCESS_CONCURRENCY)
    _metric('queued', 1)
    async with _process_slots:
        _metric('queued', -1)
        _metric('processing', 1)
        try:
            digest=await asyncio.to_thread(sha256,path)
            target=resolve_storage_target(branch,subject,full_path)
            storage_key = f"group:{target['shared_group_id']}" if target['shared_group_id'] else f"subject:{branch}:{subject}"
            acc = await asyncio.to_thread(
                account_for_storage, storage_key, int(path.stat().st_size), str(target.get('drive_account') or '')
            )
            storage_path=str(target['storage_path'])
            dup=duplicate(acc,storage_path,digest)
            fid,url=await asyncio.to_thread(upload_staging,acc,path,filename)
            i=insert({'kind':kind,'status':'pending','user_id':user_id,'username':username,'branch':branch,'subject':subject,'category':category,'full_path':full_path,'logical_path':str(target['logical_path']),'storage_path':storage_path,'shared_group_id':target['shared_group_id'],'subject_id':target['subject_id'],'filename':filename,'size_bytes':path.stat().st_size,'sha256':digest,'duplicate_of':dup['submission_id'] if dup else None,'drive_account':acc,'drive_file_id':fid,'drive_url':url,'created_at':now_iso()})
            if is_owner(user_id):await accept(i,user_id,bool(dup))
            else:await post_review(i)
            if dup:
                e=discord.Embed(title='تم اكتشاف ملف مكرر',color=discord.Color.gold()); e.add_field(name='الرافع',value=f'<@{user_id}>'); e.add_field(name='المسار',value=f'`{full_path}`',inline=False); await send_log('duplicates',e)
            _metric('completed', 1)
            return i
        except Exception:
            _metric('failed', 1)
            raise
        finally:
            _metric('processing', -1)



def enqueue_upload_job(kind: str, payload: dict[str, Any], priority: int = 100) -> int:
    """Persist a file-processing job before acknowledging the user."""
    now = now_iso()
    with _db_lock, db() as c:
        cur = c.execute(
            """INSERT INTO background_upload_jobs(
                 status,kind,payload_json,priority,attempts,max_attempts,
                 available_at,created_at,updated_at
               ) VALUES('pending',?,?,?,?,?,?,?,?)""",
            (
                kind,
                json.dumps(payload, ensure_ascii=False),
                int(priority),
                0,
                UPLOAD_QUEUE_MAX_ATTEMPTS,
                now,
                now,
                now,
            ),
        )
        c.commit()
        job_id = int(cur.lastrowid)
    _metric('queued', 1)
    return job_id


def _recover_expired_upload_jobs_sync() -> int:
    now = now_iso()
    with _db_lock, db() as c:
        cur = c.execute(
            """UPDATE background_upload_jobs
               SET status='pending', worker_id=NULL, lease_until=NULL,
                   updated_at=?, last_error=COALESCE(last_error,'') || '\nتمت استعادة المهمة بعد توقف العامل.'
               WHERE status='processing' AND lease_until IS NOT NULL AND lease_until < ?""",
            (now, now),
        )
        c.commit()
        return int(cur.rowcount)


def _claim_upload_job_sync(worker_id: str) -> Optional[dict[str, Any]]:
    now_dt = datetime.now(timezone.utc)
    now = now_dt.isoformat()
    lease_until = (now_dt + timedelta(seconds=UPLOAD_QUEUE_LEASE_SECONDS)).isoformat()
    with _db_lock, db() as c:
        c.execute('BEGIN IMMEDIATE')
        row = c.execute(
            """SELECT * FROM background_upload_jobs
               WHERE status='pending' AND available_at <= ?
               ORDER BY priority ASC, id ASC LIMIT 1""",
            (now,),
        ).fetchone()
        if not row:
            c.commit()
            return None
        updated = c.execute(
            """UPDATE background_upload_jobs
               SET status='processing', worker_id=?, lease_until=?,
                   attempts=attempts+1, updated_at=?
               WHERE id=? AND status='pending'""",
            (worker_id, lease_until, now, int(row['id'])),
        ).rowcount
        c.commit()
        if not updated:
            return None
        claimed = dict(row)
        claimed['attempts'] = int(row['attempts']) + 1
        claimed['worker_id'] = worker_id
        return claimed


def _finish_upload_job_sync(job_id: int) -> None:
    now = now_iso()
    with _db_lock, db() as c:
        c.execute(
            """UPDATE background_upload_jobs
               SET status='completed', lease_until=NULL, updated_at=?, finished_at=?
               WHERE id=?""",
            (now, now, int(job_id)),
        )
        c.commit()
    _metric('queued', -1)


def _retry_upload_job_sync(job_id: int, error: str, attempts: int, max_attempts: int) -> bool:
    now_dt = datetime.now(timezone.utc)
    terminal = attempts >= max_attempts
    delay = min(900, 5 * (2 ** max(0, attempts - 1)))
    available_at = (now_dt + timedelta(seconds=delay)).isoformat()
    status = 'failed' if terminal else 'pending'
    with _db_lock, db() as c:
        c.execute(
            """UPDATE background_upload_jobs
               SET status=?, available_at=?, lease_until=NULL, worker_id=NULL,
                   last_error=?, updated_at=?, finished_at=?
               WHERE id=?""",
            (
                status,
                available_at,
                str(error)[-4000:],
                now_dt.isoformat(),
                now_dt.isoformat() if terminal else None,
                int(job_id),
            ),
        )
        c.commit()
    if terminal:
        _metric('queued', -1)
        _metric('failed', 1)
    return terminal


def _assemble_large_job_sync(payload: dict[str, Any]) -> Path:
    session_dir = Path(str(payload['session_dir']))
    filename = clean(str(payload['filename']))
    total_chunks = int(payload['total_chunks'])
    expected_size = int(payload['size_bytes'])
    parts = [session_dir / f'{i}.part' for i in range(total_chunks)]
    if not all(part.exists() for part in parts):
        raise FileNotFoundError('أجزاء الملف غير مكتملة أو فُقدت قبل المعالجة.')
    output_path = session_dir / filename
    with _finish_slots:
        with output_path.open('wb') as target:
            for part in parts:
                with part.open('rb') as source:
                    shutil.copyfileobj(source, target, 1024 * 1024)
    if output_path.stat().st_size != expected_size:
        raise ValueError('الحجم النهائي لا يطابق الحجم المتوقع.')
    return output_path


async def _execute_upload_job(job: dict[str, Any]) -> None:
    payload = json.loads(str(job['payload_json']))
    kind = str(job['kind'])
    path: Optional[Path] = None
    cleanup_dir: Optional[Path] = None
    if kind == 'large_file':
        path = await asyncio.to_thread(_assemble_large_job_sync, payload)
        cleanup_dir = Path(str(payload['session_dir']))
    else:
        path = Path(str(payload['temp_path']))
        if not path.exists():
            raise FileNotFoundError('الملف المؤقت غير موجود.')
        cleanup_dir = path.parent if bool(payload.get('cleanup_parent')) else None

    await process_file(
        path,
        str(payload['filename']),
        int(payload['user_id']),
        str(payload['username']),
        str(payload['branch']),
        str(payload['subject']),
        str(payload['category']),
        str(payload['full_path']),
        kind,
    )

    try:
        if cleanup_dir:
            shutil.rmtree(cleanup_dir, ignore_errors=True)
        elif path:
            path.unlink(missing_ok=True)
    except Exception:
        log.exception('تعذر تنظيف ملفات المهمة %s', job['id'])


async def upload_queue_worker(worker_no: int) -> None:
    worker_id = f'upload-worker-{worker_no}-{secrets.token_hex(4)}'
    while True:
        job = await asyncio.to_thread(_claim_upload_job_sync, worker_id)
        if not job:
            await asyncio.sleep(UPLOAD_QUEUE_POLL_SECONDS)
            continue
        try:
            await _execute_upload_job(job)
            await asyncio.to_thread(_finish_upload_job_sync, int(job['id']))
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.exception('فشلت مهمة الرفع الخلفية رقم %s', job['id'])
            terminal = await asyncio.to_thread(
                _retry_upload_job_sync,
                int(job['id']),
                repr(exc),
                int(job['attempts']),
                int(job['max_attempts']),
            )
            if terminal:
                try:
                    await report_error(f"مهمة رفع خلفية #{job['id']}", exc)
                except Exception:
                    log.exception('تعذر إرسال تقرير خطأ المهمة %s', job['id'])


def make_token(s, mode: str = 'large'):
    prefix = 's_' if mode == 'small' else 'l_'
    t=prefix+secrets.token_urlsafe(32); n=int(time.time())
    with _db_lock, db() as c:
        c.execute('INSERT INTO upload_tokens VALUES(?,?,?,?,?,?,?,?,?,0)',(t,s.user_id,s.username,s.branch,s.subject,s.category,s.full_path,n,n+TOKEN_LIFE)); c.commit()
    return t


class LinkModal(discord.ui.Modal,title='إرسال رابط Google Drive'):
    link=discord.ui.TextInput(label='رابط Google Drive',min_length=8,max_length=2000)
    name=discord.ui.TextInput(label='اسم أو وصف الرابط',required=False,max_length=150)
    def __init__(self,s):super().__init__(timeout=600);self.s=s
    async def on_submit(self,it):
        error = upload_permission_error(it.user.id)
        if error:
            return await it.response.send_message(error, ephemeral=True)
        link_value = str(self.link).strip()
        if not (link_value.startswith('https://drive.google.com/') or link_value.startswith('https://docs.google.com/')):
            return await it.response.send_message('الرابط يجب أن يكون من Google Drive أو Google Docs.', ephemeral=True)
        await it.response.defer(ephemeral=True,thinking=True)
        target=resolve_storage_target(self.s.branch,self.s.subject,self.s.full_path)
        i=insert({'kind':'drive_link','status':'pending','user_id':it.user.id,'username':str(it.user),'branch':self.s.branch,'subject':self.s.subject,'category':self.s.category,'full_path':self.s.full_path,'logical_path':str(target['logical_path']),'storage_path':str(target['storage_path']),'shared_group_id':target['shared_group_id'],'subject_id':target['subject_id'],'filename':str(self.name).strip() or 'رابط Google Drive','size_bytes':0,'source_url':link_value,'created_at':now_iso()})
        if is_owner(it.user.id):await accept(i,it.user.id)
        else:await post_review(i)
        await it.followup.send('شكراً لمساهمتك في عمل الخير.',ephemeral=True)


class SmallFileUploadModal(discord.ui.Modal, title='رفع ملف صغير'):
    uploaded_file = discord.ui.Label(
        text='اختر الملف',
        description='الحد الأقصى لحجم الملف هو 10 MB.',
        component=discord.ui.FileUpload(
            custom_id='small_file_upload',
            required=True,
            min_values=1,
            max_values=1
        )
    )

    def __init__(self, state: State):
        super().__init__(timeout=600)
        self.s = state

    async def on_submit(self, interaction: discord.Interaction):
        error = upload_permission_error(interaction.user.id)
        if error:
            await interaction.response.send_message(error, ephemeral=True)
            return

        attachments = self.uploaded_file.component.values
        if not attachments:
            await interaction.response.send_message(
                'لم يتم اختيار ملف.',
                ephemeral=True
            )
            return

        attachment = attachments[0]
        filename = clean(attachment.filename)

        if not filename or not allowed_file(filename):
            await interaction.response.send_message(
                'امتداد الملف غير مسموح.',
                ephemeral=True
            )
            return

        if attachment.size <= 0 or attachment.size > SMALL_LIMIT:
            await interaction.response.send_message(
                'حجم الملف يجب ألا يتجاوز 10 MB.',
                ephemeral=True
            )
            return

        await interaction.response.defer(ephemeral=True, thinking=True)

        # نحفظ الملف أولاً، ثم نُثبت المهمة في قاعدة البيانات قبل الرد للمستخدم.
        # المعالجة الثقيلة (الفحص، Drive، المراجعة) تتم لاحقاً في الخلفية.
        job_dir = DATA / 'small_uploads' / secrets.token_hex(16)
        job_dir.mkdir(parents=True, exist_ok=True)
        temp_path = job_dir / filename

        try:
            await attachment.save(temp_path)
            await asyncio.to_thread(
                enqueue_upload_job,
                'small_file',
                {
                    'temp_path': str(temp_path),
                    'cleanup_parent': True,
                    'filename': filename,
                    'user_id': interaction.user.id,
                    'username': str(interaction.user),
                    'branch': self.s.branch,
                    'subject': self.s.subject,
                    'category': self.s.category,
                    'full_path': self.s.full_path,
                    'size_bytes': int(attachment.size),
                },
                100,
            )
            await interaction.followup.send(
                'تم استلام الملف بنجاح، شكرًا لمساهمتك في عمل الخير.',
                ephemeral=True
            )
        except Exception as exc:
            shutil.rmtree(job_dir, ignore_errors=True)
            await report_error('استلام ملف صغير', exc)
            await interaction.followup.send(
                'تعذر استلام الملف الآن. حاول مرة أخرى.',
                ephemeral=True
            )


