async def send_or_update_panel(branch: str) -> bool:
    cid = int(UPLOAD_CHANNELS.get(branch, 0) or 0)
    ch = await channel(cid)
    if not ch:
        return False
    content = f"مكتبة رفع ملفات {branch}"
    key = f"panel_message:{branch}"
    mid = get_setting(key)
    if mid:
        try:
            msg = await ch.fetch_message(int(mid))
            await msg.edit(content=content, embed=None, view=MainView())
            return True
        except Exception:
            pass
    msg = await ch.send(content, view=MainView())
    set_setting(key, str(msg.id))
    return True

@tree.command(name="تهيئة_حسابات_درايف", description="فحص وتهيئة جميع حسابات Google Drive وإنشاء المجلدات الأساسية")
@app_commands.checks.has_permissions(administrator=True)
async def initialize_drive_accounts_cmd(it: discord.Interaction):
    await it.response.defer(ephemeral=True, thinking=True)
    results = await asyncio.to_thread(initialize_all_drive_accounts_sync)
    ok = [r for r in results if r.get("status") == "ok"]
    disabled = [r for r in results if r.get("status") == "disabled"]
    unconfigured = [r for r in results if r.get("status") == "unconfigured"]
    failed = [r for r in results if r.get("status") == "error"]
    lines = [
        "🔄 **نتيجة تهيئة حسابات Google Drive**",
        f"✅ جاهز: `{len(ok)}`", f"⏸️ معطل: `{len(disabled)}`",
        f"⚪ غير مكتمل: `{len(unconfigured)}`", f"❌ فشل: `{len(failed)}`",
    ]
    for r in ok[:12]:
        pct = r.get("percent")
        pct_text = f"{float(pct):.1f}%" if pct is not None else "غير معروف"
        lines.append(f"✅ `{r['name']}` — {r.get('email') or 'بدون بريد ظاهر'} — استخدام {pct_text}")
    for r in failed[:8]:
        lines.append(f"❌ `{r['name']}` — {str(r.get('error',''))[:150]}")
    await it.followup.send("\n".join(lines)[:1900], ephemeral=True)


