@tree.command(name="حالة_حسابات_درايف", description="عرض صحة ومساحة جميع حسابات Google Drive")
@app_commands.checks.has_permissions(administrator=True)
async def drive_accounts_status_cmd(it: discord.Interaction):
    await it.response.defer(ephemeral=True, thinking=True)
    lines = ["📊 **حالة حسابات Google Drive**"]
    for name in DRIVE_ACCOUNTS:
        if not drive_account_enabled(name):
            lines.append(f"⏸️ `{name}` — معطل")
            continue
        if not _has_drive_credentials(name):
            lines.append(f"⚪ `{name}` — بيانات الدخول ناقصة")
            continue
        r = await asyncio.to_thread(drive_account_health_sync, name, True, True)
        if r.get("status") == "ok":
            pct = r.get("percent")
            pct_text = f"{float(pct):.1f}%" if pct is not None else "غير معروف"
            lines.append(f"✅ `{name}` — {r.get('email') or 'بدون بريد ظاهر'} — {pct_text}")
        else:
            lines.append(f"❌ `{name}` — {str(r.get('error',''))[:110]}")
    text = "\n".join(lines)
    if len(text) <= 1900:
        await it.followup.send(text, ephemeral=True)
    else:
        payload = io.BytesIO(text.encode("utf-8"))
        await it.followup.send("التقرير طويل؛ أرفقته كاملًا.", file=discord.File(payload, filename="drive_accounts_status.txt"), ephemeral=True)


