@app_commands.checks.has_permissions(administrator=True)
async def create_all_folders(it, معاينة: bool = False):
    await it.response.defer(ephemeral=True, thinking=True)
    if معاينة:
        lines = []
        for branch in BRANCHES:
            r = await asyncio.to_thread(folder_preview_sync, branch)
            lines.append(f"**{branch}:** ناقص `{r['missing']}` | موجود `{r['existing']}` | أخطاء `{r['failed']}`")
        return await it.followup.send("🔎 **معاينة جميع الفروع**\n" + "\n".join(lines), ephemeral=True)
    total_created = total_skipped = total_failed = 0
    for branch in BRANCHES:
        r = await create_branch_tree(branch, it.user.id, False)
        total_created += int(r['created']); total_skipped += int(r['skipped']); total_failed += int(r['failed'])
    await it.followup.send(
        f"✅ مجلدات جديدة: `{total_created}`\n⏩ موجودة وتم تخطيها: `{total_skipped}`\n❌ فشل: `{total_failed}`",
        ephemeral=True
    )

@tree.command(name="إيقاف_إنشاء_المجلدات", description="إيقاف عملية إنشاء مجلدات وحفظ مكان التوقف")
@app_commands.checks.has_permissions(administrator=True)
async def stop_folder_creation(it, رقم_العملية: int):
    job = await asyncio.to_thread(get_folder_job_sync, رقم_العملية)
    if not job:
        return await it.response.send_message("رقم العملية غير موجود.", ephemeral=True)
    if job['status'] not in ('running','pending'):
        return await it.response.send_message(f"لا يمكن إيقافها؛ حالتها الحالية: `{job['status']}`", ephemeral=True)
    set_setting(_job_cancel_key(رقم_العملية), '1')
    await it.response.send_message("⏸️ تم طلب الإيقاف. سيحفظ البوت مكانه بعد إنهاء المسار الحالي.", ephemeral=True)

