@tree.command(name="مزامنة_المكتبة", description="مزامنة الملفات المقبولة مع المكتبة — احتياط للإدارة")
@app_commands.checks.has_permissions(administrator=True)
async def manual_library_sync(it, request_id: Optional[int] = None):
    await it.response.defer(ephemeral=True,thinking=True)
    with db() as c:
        rows=c.execute("SELECT id FROM submissions WHERE status IN ('accepted','accepted_copy')" + (" AND id=?" if request_id is not None else "") + " ORDER BY id", ((request_id,) if request_id is not None else ())).fetchall()
    ok=failed=0
    for row in rows:
        sid=int(row['id']); await asyncio.to_thread(queue_library_sync_sync,sid,True)
        try: await sync_submission_to_library(sid,False); ok+=1
        except Exception as exc:
            failed+=1
            with db() as c: job=c.execute('SELECT id FROM library_sync_jobs WHERE submission_id=?',(sid,)).fetchone()
            if job: await asyncio.to_thread(mark_sync_failure_sync,int(job['id']),str(exc))
    await library_admin_log('🔄 مزامنة يدوية للمكتبة',f"**بواسطة:** <@{it.user.id}>\n**نجح:** `{ok}`\n**تعذر مؤقتًا:** `{failed}`")
    await it.followup.send(f'✅ تمت مزامنة `{ok}` ملف.\n⏳ بانتظار إعادة المحاولة: `{failed}`.',ephemeral=True)

