LTS_MONITOR_INTERVAL_SECONDS = max(60, int(os.getenv("LTS_MONITOR_INTERVAL_SECONDS", "600")))
LTS_CLEANUP_INTERVAL_HOURS = max(1, int(os.getenv("LTS_CLEANUP_INTERVAL_HOURS", "6")))
LTS_WEEKLY_REPORT_ENABLED = os.getenv("LTS_WEEKLY_REPORT_ENABLED", "true").lower() in {"1","true","yes","on"}
LTS_WEEKLY_REPORT_DAY = int(os.getenv("LTS_WEEKLY_REPORT_DAY", "0"))  # 0=Monday
LTS_WEEKLY_REPORT_HOUR_UTC = int(os.getenv("LTS_WEEKLY_REPORT_HOUR_UTC", "6"))
LTS_RAM_WARNING_MB = max(128, int(os.getenv("LTS_RAM_WARNING_MB", "420")))
LTS_ERROR_LOG_CHANNEL_ID = LIBRARY_ADMIN_CHANNEL_ID
LTS_HEALTH_REPORT_CHANNEL_ID = LIBRARY_ADMIN_CHANNEL_ID
LTS_DIAGNOSTIC_DRIVE_TEST = os.getenv("LTS_DIAGNOSTIC_DRIVE_TEST", "true").lower() in {"1","true","yes","on"}
LTS_DIAGNOSTIC_KEEP_FILES = os.getenv("LTS_DIAGNOSTIC_KEEP_FILES", "false").lower() in {"1","true","yes","on"}
LTS_VERSION = "3.1.2-drive-control"

def _choose_backup_account_sync() -> str:
    """Choose a healthy Drive account for system backups without binding backups to a branch."""
    if LONG_TERM_BACKUP_ACCOUNT:
        if drive_account_usable(LONG_TERM_BACKUP_ACCOUNT):
            return LONG_TERM_BACKUP_ACCOUNT
        raise RuntimeError(f"حساب النسخ الاحتياطي غير صالح: {LONG_TERM_BACKUP_ACCOUNT}")
    for account_name in DRIVE_ACCOUNTS:
        try:
            if drive_account_usable(account_name):
                return account_name
        except Exception:
            continue
    raise RuntimeError("لا يوجد حساب Google Drive صالح لحفظ النسخة الاحتياطية.")


def _prune_remote_backups_sync(svc, folder_id: str) -> None:
    query = f"'{folder_id}' in parents and trashed=false"
    files = svc.files().list(
        q=query, spaces='drive', orderBy='createdTime desc', pageSize=100,
        fields='files(id,name,createdTime)', supportsAllDrives=True,
        includeItemsFromAllDrives=True,
    ).execute().get('files', [])
    for old in files[LONG_TERM_BACKUP_KEEP_REMOTE:]:
        try:
            svc.files().delete(fileId=old['id'], supportsAllDrives=True).execute()
        except Exception:
            log.exception('تعذر حذف نسخة احتياطية قديمة من Drive: %s', old.get('name'))


def upload_backup_to_drive_sync(path: Path) -> dict[str, str]:
    """Upload one complete ZIP backup to a hidden system folder in Google Drive."""
    account = _choose_backup_account_sync()
    svc = service(account)
    root = effective_root_folder_id(account)
    if not root:
        raise RuntimeError(f"root_folder_id ناقص للحساب {account}")
    with _locks[account]:
        folder_id = ensure_folder(svc, root, '_SYSTEM_BACKUPS')
        media = MediaFileUpload(str(path), mimetype='application/zip', resumable=True, chunksize=8*1024*1024)
        created = svc.files().create(
            body={'name': path.name, 'parents': [folder_id]}, media_body=media,
            fields='id,webViewLink', supportsAllDrives=True,
        ).execute()
        _prune_remote_backups_sync(svc, folder_id)
    set_setting('last_remote_backup_at', now_iso())
    set_setting('last_remote_backup_account', account)
    set_setting('last_remote_backup_file_id', str(created.get('id','')))
    return {'account': account, 'file_id': str(created.get('id','')), 'url': str(created.get('webViewLink',''))}


def create_long_term_backup_sync(kind: str = 'automatic') -> tuple[Path, dict[str, str] | None]:
    path = create_full_backup_sync(kind)
    remote = None
    if LONG_TERM_BACKUP_ENABLED:
        remote = upload_backup_to_drive_sync(path)
    return path, remote


def cleanup_stale_temp_files_sync() -> dict[str, int]:
    """Clean only abandoned local files; active queue payloads are protected."""
    cutoff = time.time() - TEMP_FILE_MAX_AGE_HOURS * 3600
    protected: set[str] = set()
    try:
        with db() as c:
            rows = c.execute("SELECT payload_json FROM background_upload_jobs WHERE status IN ('pending','processing')").fetchall()
        for row in rows:
            try:
                payload = json.loads(row['payload_json'])
                for key in ('temp_path','session_dir'):
                    if payload.get(key):
                        protected.add(str(Path(str(payload[key])).resolve()))
            except Exception:
                continue
    except Exception:
        log.exception('تعذر قراءة مسارات الطابور أثناء التنظيف')
    removed_files = removed_dirs = 0
    for root in (CHUNKS, DATA / 'tmp', DATA / 'uploads'):
        if not root.exists():
            continue
        for item in list(root.iterdir()):
            try:
                resolved = str(item.resolve())
                if any(resolved == p or p.startswith(resolved + os.sep) for p in protected):
                    continue
                if item.stat().st_mtime >= cutoff:
                    continue
                if item.is_dir():
                    shutil.rmtree(item, ignore_errors=True); removed_dirs += 1
                else:
                    item.unlink(missing_ok=True); removed_files += 1
            except Exception:
                log.exception('تعذر تنظيف ملف مؤقت: %s', item)
    return {'files': removed_files, 'dirs': removed_dirs}


def backup_database_sync() -> None:
    if not DB_PATH.exists():
        return
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d_%H-%M-%S")
    target = BACKUPS / f"upload_bot_{stamp}.sqlite3"
    shutil.copy2(DB_PATH, target)
    cutoff = time.time() - BACKUP_KEEP_DAYS * 86400
    for file in BACKUPS.glob("upload_bot_*.sqlite3"):
        if file.stat().st_mtime < cutoff:
            file.unlink(missing_ok=True)

@tasks.loop(hours=LONG_TERM_BACKUP_INTERVAL_HOURS)
async def backup_loop():
    try:
        path, remote = await asyncio.to_thread(create_long_term_backup_sync, 'automatic')
        await asyncio.to_thread(cleanup_stale_temp_files_sync)
        if remote:
            log.info("LONG_TERM_BACKUP success file=%s account=%s", path.name, remote['account'])
        else:
            log.info("LOCAL_BACKUP success file=%s", path.name)
    except Exception as exc:
        await report_error("النسخ الاحتياطي طويل المدى", exc)

BOT_INITIALIZED = False

@bot.event
async def on_ready():
    global BOT_INITIALIZED
    if BOT_INITIALIZED:
        log.info("أُعيد اتصال البوت: %s", bot.user)
        return
    BOT_INITIALIZED = True
    bot.add_view(MainView())
    bot.add_view(StatisticsPanelView())
    _branding_db_ready()
    # استعادة أحدث الواجهات الدائمة فقط لحماية RAM على Render المجاني.
    # الطلبات الأقدم تبقى محفوظة في قاعدة البيانات ويمكن إدارتها بالأوامر.
    with db() as c:
        branding_rows = c.execute(
            "SELECT submission_id FROM branding_jobs WHERE status NOT IN ('rejected') "
            "ORDER BY submission_id DESC LIMIT ?",
            (MAX_RESTORED_BRANDING_VIEWS,),
        ).fetchall()
    for bj in branding_rows:
        bot.add_view(BrandingApprovalView(int(bj['submission_id'])))
    del branding_rows

    with db() as c:
        rows = c.execute(
            "SELECT id FROM submissions WHERE status='pending' ORDER BY id DESC LIMIT ?",
            (MAX_RESTORED_REVIEW_VIEWS,),
        ).fetchall()
    for r in rows:
        bot.add_view(ReviewView(int(r['id'])))
    del rows
    gc.collect()
    if not stats_loop.is_running():
        stats_loop.start()
    if not backup_loop.is_running():
        backup_loop.start()
        if STARTUP_BACKUP_ENABLED:
            async def _delayed_startup_backup():
                await asyncio.sleep(STARTUP_BACKUP_DELAY_SECONDS)
                await asyncio.to_thread(create_long_term_backup_sync, 'startup')
                gc.collect()
            asyncio.create_task(_delayed_startup_backup(), name='delayed-startup-backup')
    if not library_sync_loop.is_running():
        library_sync_loop.start()
    try:
        if GUILD_ID:
            g=discord.Object(id=GUILD_ID)
            tree.copy_global_to(guild=g)
            await tree.sync(guild=g)
        else:
            await tree.sync()
    except Exception as exc:
        await report_error("مزامنة أوامر Discord", exc)
    log.info('البوت جاهز: %s',bot.user)

