@app.post('/admin/uploads/retry/<int:job_id>')
def admin_upload_retry(job_id: int):
    denied = _dashboard_guard()
    if denied:
        return denied
    ok = _retry_dashboard_job_sync(job_id)
    token = request.args.get('token', '') or request.form.get('token', '')
    return Response('', 303, headers={'Location': f'/admin/uploads?token={token}&retry={"ok" if ok else "not-found"}'})


@app.post('/admin/uploads/retry-all')
def admin_upload_retry_all():
    denied = _dashboard_guard()
    if denied:
        return denied
    count = _retry_all_dashboard_jobs_sync()
    token = request.args.get('token', '') or request.form.get('token', '')
    return Response('', 303, headers={'Location': f'/admin/uploads?token={token}&retried={count}'})


