LIBRARY_SPECIALIZATION_ROLES = {
 "طالب علمي":"علمي","طالبة علمي":"علمي","طالب أدبي":"أدبي","طالبة أدبي":"أدبي",
 "طالب صناعي":"صناعي","طالبة صناعي":"صناعي","طالب تجاري":"تجاري","طالبة تجاري":"تجاري",
 "طالب زراعي":"زراعي","طالبة زراعي":"زراعي","طالب فندقي":"فندقي","طالبة فندقي":"فندقي",
 "طالب اقتصاد منزلي":"اقتصاد منزلي","طالبة اقتصاد منزلي":"اقتصاد منزلي","طالب شرعي":"شرعي","طالبة شرعي":"شرعي"
}
LIBRARY_MESSAGE_LIMIT=1950

def library_is_admin(m):
    return m.id in OWNER_IDS or m.guild_permissions.administrator or bool({r.id for r in m.roles}&{x for x in LIBRARY_ADMIN_ROLE_IDS if x})

def normalize_library_entry(k,v):
    if isinstance(v,str):
        u=v.strip()
        return None if not u or u=='ضع_الرابط_هنا' else {'key':k,'title':k,'url':u,'description':'','admin_only':False,'hidden':False}
    if isinstance(v,dict) and _entry_url(v):
        return {'key':k,'title':str(v.get('title') or k),'url':_entry_url(v),'description':str(v.get('description') or ''),'admin_only':bool(v.get('admin_only')),'hidden':bool(v.get('hidden'))}
    return None

def library_leaf_entries(node,include_admin=False):
    if not isinstance(node,dict): return None
    vals=[]
    for k,v in node.items():
        e=normalize_library_entry(str(k),v)
        if e:
            if not e['hidden'] and (include_admin or not e['admin_only']): vals.append(e)
        elif isinstance(v,dict): return None
    return vals if vals else None

def format_library_entry(e):
    out=('👑 ' if e['admin_only'] else '📄 ')+e['title']
    if e['description'].strip(): out+='\n\n'+e['description'].strip()
    return out+'\n\n'+e['url']

def split_library_entries(entries):
    out=[]; blocks=[]; keys=[]
    for e in entries:
        block=format_library_entry(e)
        if len(block)>LIBRARY_MESSAGE_LIMIT:
            base=('👑 ' if e['admin_only'] else '📄 ')+e['title']+'\n\n'+e['url']
            keep=max(0,LIBRARY_MESSAGE_LIMIT-len(base)-2)
            block=('👑 ' if e['admin_only'] else '📄 ')+e['title']+(('\n\n'+e['description'][:keep]) if keep else '')+'\n\n'+e['url']
        test='\n\n\n'.join(blocks+[block])
        if blocks and len(test)>LIBRARY_MESSAGE_LIMIT:
            out.append(('\n\n\n'.join(blocks),keys)); blocks=[block]; keys=[e['key']]
        else: blocks.append(block); keys.append(e['key'])
    if blocks: out.append(('\n\n\n'.join(blocks),keys))
    return out

def load_library_node(path):
    n=_load_materials_json_sync()
    for k in path:
        if not isinstance(n,dict) or k not in n:return None
        n=n[k]
    return n

def save_render_mapping(msg,path,idx,keys):
    now=now_iso()
    with _db_lock,db() as c:
        c.execute("INSERT INTO library_render_messages(message_id,channel_id,guild_id,json_path,chunk_index,entry_keys,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(message_id) DO UPDATE SET json_path=excluded.json_path,entry_keys=excluded.entry_keys,updated_at=excluded.updated_at",(msg.id,msg.channel.id,msg.guild.id if msg.guild else None,json.dumps(path,ensure_ascii=False),idx,json.dumps(keys,ensure_ascii=False),now,now));c.commit()

def get_render_mapping(mid):
    with db() as c:return c.execute('SELECT * FROM library_render_messages WHERE message_id=?',(mid,)).fetchone()

def parse_edited_library_message(text):
    import re
    blocks=[x.strip() for x in re.split(r'\n\s*\n\s*\n+',text.strip()) if x.strip()]
    ans=[]
    for b in blocks:
        lines=[x.strip() for x in b.splitlines() if x.strip()]
        if len(lines)<2 or not re.fullmatch(r'https?://\S+',lines[-1]):raise ValueError('كل ملف لازم يكون: الاسم، ثم الرابط الكامل في آخر سطر.')
        title=lines[0].removeprefix('📄').removeprefix('👑').strip()
        ans.append({'title':title,'description':'\n'.join(lines[1:-1]),'url':lines[-1]})
    if not ans:raise ValueError('لا يوجد ملفات صالحة.')
    return ans

def apply_message_edit_sync(mapping,items,actor):
    path=json.loads(mapping['json_path']); old_keys=json.loads(mapping['entry_keys'])
    with _materials_lock:
        data=_load_materials_json_sync(); node=data
        for p in path:node=node[p]
        old=[node.get(k) for k in old_keys]; all_keys=list(node); pos=min([all_keys.index(k) for k in old_keys if k in all_keys] or [len(all_keys)])
        for k in old_keys:node.pop(k,None)
        pairs=[];used=set(node)
        for i,item in enumerate(items):
            key=item['title'];base=key;n=2
            while key in used:key=f'{base} ({n})';n+=1
            used.add(key); ov=old[i] if i<len(old) and isinstance(old[i],dict) else {}
            pairs.append((key,{'title':item['title'],'description':item['description'],'url':item['url'],'admin_only':bool(ov.get('admin_only')),'hidden':bool(ov.get('hidden'))}))
        arr=list(node.items())
        for pair in reversed(pairs):arr.insert(pos,pair)
        node.clear();node.update(arr);_save_materials_json_atomic_sync(data)
    with _db_lock,db() as c:
        c.execute("INSERT INTO library_audit_log(action,actor_id,full_path,details,created_at) VALUES('edit_message',?,?,?,?)",(actor,' > '.join(path),json.dumps(items,ensure_ascii=False),now_iso()));c.commit()

class LibraryMessageEditModal(discord.ui.Modal,title='تعديل رسالة المكتبة'):
    content=discord.ui.TextInput(label='المحتوى',style=discord.TextStyle.paragraph,max_length=4000)
    def __init__(self,msg):super().__init__();self.msg=msg;self.content.default=msg.content[:4000]
    async def on_submit(self,it):
        if not library_is_admin(it.user):await it.response.send_message('للإدارة فقط.',ephemeral=True);return
        mp=get_render_mapping(self.msg.id)
        if not mp:await it.response.send_message('الرسالة غير مرتبطة بالمكتبة.',ephemeral=True);return
        try:
            items=parse_edited_library_message(str(self.content.value));await asyncio.to_thread(apply_message_edit_sync,mp,items,it.user.id)
            await self.msg.edit(content=str(self.content.value)[:2000]);await it.response.send_message('✅ تعدلت الرسالة وmaterials.json تلقائيًا.',ephemeral=True)
        except Exception as e:await it.response.send_message(f'خطأ: {e}',ephemeral=True)

class LibraryChunkAdminView(discord.ui.View):
    def __init__(self):super().__init__(timeout=None)
    @discord.ui.button(label='✏️ تعديل الرسالة',style=discord.ButtonStyle.secondary,custom_id='library_edit_chunk_v2')
    async def edit(self,it,b):
        if not library_is_admin(it.user):await it.response.send_message('للإدارة فقط.',ephemeral=True);return
        await it.response.send_modal(LibraryMessageEditModal(it.message))



# =========================================================
# v3.1.1 LTS FINAL — مراقبة ذاتية، Watchdog، تقرير أسبوعي، تشخيص فعلي
# =========================================================
_lts_worker_tasks: dict[int, asyncio.Task] = {}
_lts_last_weekly_key = ""
_lts_monitor_state: dict[str, Any] = {"last_run": "", "health_score": 0, "warnings": []}
_lts_last_ram_alert_at = 0.0
LTS_RAM_ALERT_COOLDOWN_SECONDS = max(300, int(os.getenv('LTS_RAM_ALERT_COOLDOWN_SECONDS', '3600')))


def _process_rss_mb() -> float:
    """Best-effort RSS reading without adding a mandatory dependency."""
    try:
        import psutil  # optional
        return psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024)
    except Exception:
        try:
            import resource
            value = float(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
            # Linux reports KiB; macOS reports bytes.
            return value / 1024 if value < 10_000_000 else value / (1024 * 1024)
        except Exception:
            return 0.0


def _queue_snapshot_sync() -> dict[str, int]:
    with db() as c:
        rows = c.execute("SELECT status, COUNT(*) n FROM background_upload_jobs GROUP BY status").fetchall()
    result = {str(r['status']): int(r['n']) for r in rows}
    for key in ('pending','processing','retry','completed','failed'):
        result.setdefault(key, 0)
    return result


def _weekly_stats_sync() -> dict[str, Any]:
    since = (datetime.now(timezone.utc) - timedelta(days=7)).isoformat()
    with db() as c:
        total = int(c.execute("SELECT COUNT(*) n FROM submissions WHERE created_at>=?", (since,)).fetchone()['n'])
        accepted = int(c.execute("SELECT COUNT(*) n FROM submissions WHERE created_at>=? AND status IN ('accepted','accepted_copy')", (since,)).fetchone()['n'])
        rejected = int(c.execute("SELECT COUNT(*) n FROM submissions WHERE created_at>=? AND status='rejected'", (since,)).fetchone()['n'])
        pending = int(c.execute("SELECT COUNT(*) n FROM submissions WHERE status='pending'").fetchone()['n'])
        top_subject = c.execute("SELECT subject,COUNT(*) n FROM submissions WHERE created_at>=? GROUP BY subject ORDER BY n DESC LIMIT 1", (since,)).fetchone()
        top_branch = c.execute("SELECT branch,COUNT(*) n FROM submissions WHERE created_at>=? GROUP BY branch ORDER BY n DESC LIMIT 1", (since,)).fetchone()
        q = _queue_snapshot_sync()
    return {
        'total': total, 'accepted': accepted, 'rejected': rejected, 'pending': pending,
        'top_subject': (str(top_subject['subject']), int(top_subject['n'])) if top_subject else ('لا يوجد',0),
        'top_branch': (str(top_branch['branch']), int(top_branch['n'])) if top_branch else ('لا يوجد',0),
        'queue': q,
    }


def _health_score_sync() -> tuple[int, list[str], dict[str, tuple[str,str]]]:
    checks = platform_self_check_sync()
    warnings: list[str] = []
    score = 100
    for name, (status, details) in checks.items():
        if status != 'ok':
            score -= 8
            warnings.append(f"{name}: {details}")
    q = _queue_snapshot_sync()
    if q['failed']:
        score -= min(20, q['failed'] * 2)
        warnings.append(f"مهام فاشلة نهائيًا: {q['failed']}")
    rss = _process_rss_mb()
    if rss and rss >= LTS_RAM_WARNING_MB:
        score -= 10
        warnings.append(f"استهلاك الذاكرة مرتفع: {rss:.0f} MB")
    return max(0, min(100, score)), warnings, checks


async def _lts_send_channel(channel_id: int, *, content: str | None = None, embed: discord.Embed | None = None) -> None:
    if not channel_id:
        return
    try:
        ch = await channel(channel_id)
        if ch:
            await ch.send(content=content, embed=embed)
    except Exception:
        log.exception('تعذر إرسال رسالة LTS إلى القناة %s', channel_id)


async def _lts_worker_supervisor_loop() -> None:
    """Keep the configured durable-queue workers alive forever."""
    while True:
        try:
            for worker_id in range(1, UPLOAD_QUEUE_WORKERS + 1):
                task = _lts_worker_tasks.get(worker_id)
                if task is None or task.done():
                    if task is not None:
                        try:
                            exc = task.exception()
                            if exc:
                                await report_error(f'Watchdog Worker #{worker_id}', exc)
                        except asyncio.CancelledError:
                            pass
                        except Exception:
                            pass
                    _lts_worker_tasks[worker_id] = asyncio.create_task(
                        upload_queue_worker(worker_id), name=f'upload-worker-{worker_id}'
                    )
                    log.warning('LTS Watchdog شغّل Worker #%s', worker_id)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            await report_error('LTS Worker Watchdog', exc)
        await asyncio.sleep(15)


async def _lts_monitor_loop() -> None:
    global _lts_monitor_state, _lts_last_ram_alert_at
    while True:
        try:
            score, warnings, checks = await asyncio.to_thread(_health_score_sync)
            _lts_monitor_state = {'last_run': now_iso(), 'health_score': score, 'warnings': warnings}
            rss = _process_rss_mb()
            q = await asyncio.to_thread(_queue_snapshot_sync)
            log.info('LTS HEALTH score=%s rss=%.1fMB pending=%s processing=%s failed=%s', score, rss, q['pending'], q['processing'], q['failed'])
            if rss and rss >= LTS_RAM_WARNING_MB:
                try:
                    import gc
                    gc.collect()
                except Exception:
                    pass
            should_alert = score < 80 or warnings
            now_ts = time.time()
            ram_only = bool(warnings) and all('الذاكرة' in w for w in warnings)
            if should_alert and (not ram_only or now_ts - _lts_last_ram_alert_at >= LTS_RAM_ALERT_COOLDOWN_SECONDS):
                embed = discord.Embed(title='⚠️ تنبيه المراقبة الذاتية', color=discord.Color.orange(), timestamp=datetime.now(timezone.utc))
                embed.add_field(name='درجة الصحة', value=f'`{score}%`', inline=True)
                embed.add_field(name='RAM', value=f'`{rss:.0f} MB`' if rss else 'غير متاح', inline=True)
                embed.add_field(name='الطابور', value=f"معلق `{q['pending']}` • معالجة `{q['processing']}` • فشل `{q['failed']}`", inline=False)
                embed.description = '\n'.join(f'• {w}' for w in warnings[:12]) or 'يوجد تحذير يحتاج مراجعة.'
                await _lts_send_channel(LTS_HEALTH_REPORT_CHANNEL_ID, embed=embed)
                if ram_only:
                    _lts_last_ram_alert_at = now_ts
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            await report_error('LTS Self Monitor', exc)
        await asyncio.sleep(LTS_MONITOR_INTERVAL_SECONDS)


async def _lts_cleanup_loop() -> None:
    while True:
        try:
            result = await asyncio.to_thread(cleanup_stale_temp_files_sync)
            recovered = await asyncio.to_thread(_recover_expired_upload_jobs_sync)
            import gc
            gc.collect()
            log.info('LTS CLEANUP files=%s dirs=%s recovered=%s', result['files'], result['dirs'], recovered)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            await report_error('LTS Auto Cleanup', exc)
        await asyncio.sleep(LTS_CLEANUP_INTERVAL_HOURS * 3600)


async def _lts_weekly_report_loop() -> None:
    global _lts_last_weekly_key
    while True:
        try:
            now = datetime.now(timezone.utc)
            iso = now.isocalendar()
            key = f'{iso.year}-{iso.week}'
            if (LTS_WEEKLY_REPORT_ENABLED and now.weekday() == LTS_WEEKLY_REPORT_DAY
                    and now.hour >= LTS_WEEKLY_REPORT_HOUR_UTC and key != _lts_last_weekly_key):
                st = await asyncio.to_thread(_weekly_stats_sync)
                score, warnings, _ = await asyncio.to_thread(_health_score_sync)
                e = discord.Embed(title='📊 التقرير الأسبوعي — الفهرس الأكاديمي', color=discord.Color.green() if score >= 90 else discord.Color.orange(), timestamp=now)
                e.add_field(name='الطلبات خلال 7 أيام', value=f"`{st['total']}`", inline=True)
                e.add_field(name='المقبولة', value=f"`{st['accepted']}`", inline=True)
                e.add_field(name='المرفوضة', value=f"`{st['rejected']}`", inline=True)
                e.add_field(name='بانتظار المراجعة', value=f"`{st['pending']}`", inline=True)
                e.add_field(name='أكثر مادة', value=f"{st['top_subject'][0]} (`{st['top_subject'][1]}`)", inline=True)
                e.add_field(name='أكثر فرع', value=f"{st['top_branch'][0]} (`{st['top_branch'][1]}`)", inline=True)
                e.add_field(name='صحة النظام', value=f"`{score}%`", inline=True)
                e.add_field(name='الطابور', value=f"معلق `{st['queue']['pending']}` • فشل `{st['queue']['failed']}`", inline=False)
                if warnings:
                    e.add_field(name='ملاحظات', value='\n'.join(f'• {x}' for x in warnings[:8])[:1024], inline=False)
                await _lts_send_channel(LTS_HEALTH_REPORT_CHANNEL_ID, embed=e)
                _lts_last_weekly_key = key
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            await report_error('LTS Weekly Report', exc)
        await asyncio.sleep(1800)


def _diagnostic_pipeline_sync() -> dict[str, Any]:
    """Run a real, reversible local + Drive diagnostic without touching the public library."""
    import fitz
    stamp = datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')
    work = DATA / 'diagnostics' / stamp
    work.mkdir(parents=True, exist_ok=True)
    source = work / 'diagnostic-source.pdf'
    branded = work / 'diagnostic-branded.pdf'
    doc = fitz.open()
    page = doc.new_page(width=595, height=842)
    page.insert_text((72, 100), f'Tawjihi LTS Diagnostic {stamp}', fontsize=16)
    page.insert_text((72, 140), 'This temporary file validates PDF creation, hashing and Drive upload.', fontsize=10)
    doc.save(source)
    doc.close()
    digest_before = sha256_file(source)
    # Validate embedded identity bytes and write a simple visible mark into a copy.
    logo_path = write_embedded_brand_logo(work / 'brand-logo.png')
    doc = fitz.open(source)
    page = doc[0]
    rect = fitz.Rect(380, 35, 555, 105)
    page.insert_image(rect, filename=str(logo_path), keep_proportion=True, overlay=True)
    page.insert_text((72, 800), DISCORD_COMMUNITY_URL[:100], fontsize=8)
    doc.save(branded)
    doc.close()
    digest_after = sha256_file(branded)
    if digest_before == digest_after:
        raise RuntimeError('فشل اختبار تعديل PDF: البصمة لم تتغير')
    remote: dict[str, Any] | None = None
    if LTS_DIAGNOSTIC_DRIVE_TEST:
        account = _choose_backup_account_sync()
        svc = service(account)
        root = effective_root_folder_id(account)
        with _locks[account]:
            folder_id = ensure_folder(svc, root, '_SYSTEM_DIAGNOSTICS')
            media = MediaFileUpload(str(branded), mimetype='application/pdf', resumable=True, chunksize=1024*1024)
            created = svc.files().create(body={'name': branded.name, 'parents':[folder_id]}, media_body=media, fields='id,webViewLink,size', supportsAllDrives=True).execute()
            remote = {'account': account, 'id': str(created.get('id','')), 'url': str(created.get('webViewLink',''))}
            if not LTS_DIAGNOSTIC_KEEP_FILES and remote['id']:
                svc.files().delete(fileId=remote['id'], supportsAllDrives=True).execute()
                remote['deleted'] = True
    # Real backup creation validates DB packaging; remote backup loop remains separate.
    backup_path = create_full_backup_sync('diagnostic')
    return {
        'source_size': source.stat().st_size,
        'branded_size': branded.stat().st_size,
        'sha_before': digest_before,
        'sha_after': digest_after,
        'backup': backup_path.name,
        'remote': remote,
        'workdir': str(work),
    }


def build_library_bot():
    """واجهة توافق قديمة فقط. عند تشغيل library_bot.py المحدث منفصلًا لا تستدعِ هذه الدالة من main.py."""
    ii=discord.Intents.default();ii.members=True;ii.message_content=True
    lib=commands.Bot(command_prefix='!lib_',intents=ii)
    def spec(m):
        names={r.name for r in m.roles}
        return next((v for k,v in LIBRARY_SPECIALIZATION_ROLES.items() if k in names),None)
    class Nav(discord.ui.View):
        def __init__(self,path,page=0,admin=False):
            super().__init__(timeout=600);self.path=path;self.page=page;self.admin=admin;n=load_library_node(path);leaf=library_leaf_entries(n,admin)
            if leaf is not None:
                b=discord.ui.Button(label='📄 عرض الملفات',style=discord.ButtonStyle.success);b.callback=self.show;self.add_item(b)
            else:
                keys=list(n) if isinstance(n,dict) else [];start=page*20
                for i,k in enumerate(keys[start:start+20]):
                    b=discord.ui.Button(label=str(k)[:80],style=discord.ButtonStyle.primary,row=i//4);b.callback=self.cb(k);self.add_item(b)
                if start:b=discord.ui.Button(label='« السابق',row=4);b.callback=self.pg(page-1);self.add_item(b)
                if start+20<len(keys):b=discord.ui.Button(label='التالي »',row=4);b.callback=self.pg(page+1);self.add_item(b)
            if len(path)>1:b=discord.ui.Button(label='⬅️ رجوع',style=discord.ButtonStyle.danger,row=4);b.callback=self.back;self.add_item(b)
        def cb(self,k):
            async def f(it):await it.response.edit_message(content='📂 '+' > '.join(self.path+[k]),view=Nav(self.path+[k],0,self.admin))
            return f
        def pg(self,p):
            async def f(it):await it.response.edit_message(view=Nav(self.path,p,self.admin))
            return f
        async def back(self,it):
            p=self.path[:-1];await it.response.edit_message(content='📂 '+' > '.join(p),view=Nav(p,0,self.admin))
        async def show(self,it):
            chunks=split_library_entries(library_leaf_entries(load_library_node(self.path),self.admin) or [])
            await it.response.send_message('📚 الملفات:',ephemeral=not self.admin)
            for idx,(txt,keys) in enumerate(chunks):
                msg=await it.followup.send(txt,ephemeral=not self.admin,view=LibraryChunkAdminView() if self.admin else None,wait=True)
                if self.admin and isinstance(msg,discord.Message):save_render_mapping(msg,self.path,idx,keys)
